/* ---------- GCSE Maths: 6. Statistics. Charts are drawn as inline SVG. Lists used for quartiles have 4k + 3 values,
   so the (n + 1)/4 rule and the "median of each half" rule give the same answer. ---------- */
(()=>{const {add,rd,sf,svgG,pickn,mins,rat,GR}=MH;
const X=(q,o,m,w)=>Q(q,o.a,m,w,{d:o.d,alt:o.alt});
const sum=a=>a.reduce((s,x)=>s+x,0),mean=a=>sum(a)/a.length,srt=a=>a.slice().sort((x,y)=>x-y);
const med=a=>{const s=srt(a),n=s.length;return n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2};
const lst=(n,lo,hi)=>Array.from({length:n},()=>r(lo,hi));
const mode1=()=>{let a,c,m;do{a=lst(r(7,11),1,15);c={};a.forEach(x=>c[x]=(c[x]||0)+1);const mx=Math.max(...Object.values(c));m=Object.keys(c).filter(k=>c[k]==mx)}while(m.length!=1||c[m[0]]<2);return[a,+m[0]]};
const quart=s=>{const n=s.length,k=(n+1)/4;return[s[k-1],s[2*k-1],s[3*k-1]]};   /* n = 4k + 3 → exact positions */
const qlist=()=>{const k=r(1,3),n=4*k+3;return srt(lst(n,r(1,20),r(30,80)))};
const tbl=(h,rows)=>`<br><table style="border-collapse:collapse;margin:8px 0;font-size:.95rem"><tr>${h.map(x=>`<th style="padding:4px 10px;border:1px solid var(--bd)">${x}</th>`).join('')}</tr>${rows.map(r1=>`<tr>${r1.map(x=>`<td style="padding:4px 10px;border:1px solid var(--bd)">${x}</td>`).join('')}</tr>`).join('')}</table>`;
const W='width:100%;max-width:340px;display:block;margin:8px 0';
/* pie chart: slices [[label, angle]] */
const pie=sl=>{let a0=-90,g='';const cx=110,cy=100,R=85;sl.forEach(([lab,ang],i)=>{const a1=a0+ang,l=ang>180?1:0;const p=a=>[cx+R*Math.cos(a*Math.PI/180),cy+R*Math.sin(a*Math.PI/180)];const [x0,y0]=p(a0),[x1,y1]=p(a1);g+=`<path d="M${cx},${cy} L${x0.toFixed(1)},${y0.toFixed(1)} A${R},${R} 0 ${l} 1 ${x1.toFixed(1)},${y1.toFixed(1)} Z" fill="var(--pr)" fill-opacity="${0.12+0.17*i}" stroke="currentColor"/>`;const [tx,ty]=[cx+R*0.62*Math.cos((a0+ang/2)*Math.PI/180),cy+R*0.62*Math.sin((a0+ang/2)*Math.PI/180)];g+=`<text x="${tx.toFixed(1)}" y="${(ty+4).toFixed(1)}" font-size="11" text-anchor="middle" fill="currentColor">${lab}</text>`;a0=a1});return `<br><svg viewBox="0 0 220 200" style="${W};max-width:260px" role="img" aria-label="pie chart">${g}</svg>`};
/* box plot on a number line */
const box=(pl,lo,hi)=>{const sx=v=>20+(v-lo)/(hi-lo)*280;let g=`<line x1="20" y1="110" x2="300" y2="110" stroke="currentColor"/>`;const st=(hi-lo)/10;for(let v=lo;v<=hi+1e-9;v+=st)g+=`<line x1="${sx(v)}" y1="106" x2="${sx(v)}" y2="114" stroke="currentColor"/><text x="${sx(v)}" y="128" font-size="10" text-anchor="middle" fill="currentColor">${+v.toFixed(2)}</text>`;pl.forEach(([mn,q1,m,q3,mx,lab],i)=>{const y=30+i*40;g+=`<line x1="${sx(mn)}" y1="${y}" x2="${sx(q1)}" y2="${y}" stroke="currentColor"/><line x1="${sx(q3)}" y1="${y}" x2="${sx(mx)}" y2="${y}" stroke="currentColor"/><rect x="${sx(q1)}" y="${y-12}" width="${sx(q3)-sx(q1)}" height="24" fill="var(--pr)" fill-opacity=".15" stroke="currentColor"/><line x1="${sx(m)}" y1="${y-12}" x2="${sx(m)}" y2="${y+12}" stroke="currentColor" stroke-width="2"/><line x1="${sx(mn)}" y1="${y-7}" x2="${sx(mn)}" y2="${y+7}" stroke="currentColor"/><line x1="${sx(mx)}" y1="${y-7}" x2="${sx(mx)}" y2="${y+7}" stroke="currentColor"/>`+(lab?`<text x="${sx(lo)}" y="${y-16}" font-size="11" fill="currentColor">${lab}</text>`:'')});return `<br><svg viewBox="0 0 320 140" style="${W}" role="img" aria-label="box plot">${g}</svg>`};
/* five-number summary with nice values */
const five=(lo,hi,step=2)=>{let v;do v=srt(Array.from({length:5},()=>lo+step*r(0,(hi-lo)/step)));while(new Set(v).size<5);return v};

/* ===== Sampling ===== */
add('Statistics','Sampling',[
/* Easy */[
()=>M(`Which is the best way to choose a random sample of 50 students from a school? Options: give every student a number and use a random number generator;  ask the first 50 students who arrive;  ask 50 of your friends;  ask the 50 tallest students`,['give every student a number and use a random number generator','ask the first 50 students who arrive','ask 50 of your friends','ask the 50 tallest students'],`In a random sample every member of the population has an equal chance of being chosen.`),
()=>{const o=[['the whole group you want to find out about','population'],['a smaller group chosen from the population','sample'],['data collected by you for your own purpose','primary data'],['data already collected by someone else','secondary data']];const i=r(0,3);return M(`What is the name for ${o[i][0]}? Options: population;  sample;  primary data;  secondary data`,[o[i][1],...o.filter((_,j)=>j!=i).map(x=>x[1])],`Population = everyone; sample = some of them. Primary = collected yourself; secondary = collected by others.`)},
()=>{const p=pick([200,400,500,800,1000]),k=pick([10,20,25]);return Q(`A school has ${p} students. A ${k}% sample is taken. How many students are in the sample?`,p*k/100,`Find ${k}% of ${p}.`,`${k}/100 × ${p} = ${p*k/100}`)},
()=>M(`A survey about sport is done by asking people leaving a football match. Why might the sample be biased? Options: they are more likely to like sport than people in general;  the sample is too large;  the questions are too short;  football matches are random`,['they are more likely to like sport than people in general','the sample is too large','the questions are too short','football matches are random'],`A sample is biased if some groups are more (or less) likely to be included.`),
()=>M(`Which is an advantage of using a sample rather than the whole population? Options: it is quicker and cheaper;  it is always more accurate;  it includes everyone;  it cannot be biased`,['it is quicker and cheaper','it is always more accurate','it includes everyone','it cannot be biased'],`A sample takes less time and money, but may be less accurate than a full census.`)],
/* Moderate */[
()=>{const g=[r(10,40),r(10,40),r(10,40)];const t=sum(g),n=pick([20,30,40,50]);const i=r(0,2);return Q(`A club has ${g[0]} juniors, ${g[1]} adults and ${g[2]} seniors. A stratified sample of ${n} members is taken. How many ${['juniors','adults','seniors'][i]} should be in the sample? (Round to the nearest whole number.)`,Math.round(g[i]/t*n),`Stratified sample: each group is sampled in proportion to its size: (group ÷ total) × sample size.`,`${g[i]} ÷ ${t} × ${n} = ${rd(g[i]/t*n,3)} ≈ ${Math.round(g[i]/t*n)}`)},
()=>{const y=[r(80,200),r(80,200),r(80,200),r(80,200),r(80,200)];const t=sum(y),n=pick([50,60,80,100]);const i=r(0,4);return Q(`A school has Years 7 to 11 with ${y.join(', ')} students. A stratified sample of ${n} is taken. How many students from Year ${7+i} should be chosen? (Nearest whole number.)`,Math.round(y[i]/t*n),`Use the proportion of students in Year ${7+i}.`,`${y[i]} ÷ ${t} × ${n} = ${rd(y[i]/t*n,3)} ≈ ${Math.round(y[i]/t*n)}`)},
()=>M(`A researcher picks every 10th name from an alphabetical list. What type of sampling is this? Options: systematic;  stratified;  random;  opportunity (convenience)`,['systematic','stratified','random','opportunity (convenience)'],`Choosing at regular intervals from a list is systematic sampling.`),
()=>{const n=pick([30,40,50]);return M(`Why is a sample of ${n} usually better than a sample of 5? Options: a larger sample gives more reliable results;  a smaller sample is always biased;  a larger sample is always unbiased;  there is no difference`,['a larger sample gives more reliable results','a smaller sample is always biased','a larger sample is always unbiased','there is no difference'],`Larger samples reduce the effect of chance variation, though they can still be biased.`)},
()=>{const g=r(100,300),b=r(100,300),n=pick([40,50,60]);return Q(`A school has ${g} girls and ${b} boys. A stratified sample of ${n} students is chosen by gender. How many girls are in the sample? (Nearest whole number.)`,Math.round(g/(g+b)*n),`Girls make up ${g}/${g+b} of the school.`,`${g} ÷ ${g+b} × ${n} = ${rd(g/(g+b)*n,3)} ≈ ${Math.round(g/(g+b)*n)}`)}],
/* Difficult */[
()=>{const M0=r(30,80),T=r(30,80),R=r(4,15);return Q(`Capture–recapture: ${M0} birds are caught, ringed and released. Later ${T} birds are caught, and ${R} of them have rings. Estimate the population, to the nearest whole number.`,Math.round(M0*T/R),`Assume the proportion ringed in the second catch matches the whole population: N = (first catch × second catch) ÷ number marked in second catch.`,`N = ${M0} × ${T} ÷ ${R} = ${rd(M0*T/R,2)} ≈ ${Math.round(M0*T/R)}`)},
()=>M(`Which assumption is needed for the capture–recapture method? Options: the population does not change between the two samples;  every animal is caught in the first sample;  the marked animals stay together;  the second sample is larger than the first`,['the population does not change between the two samples','every animal is caught in the first sample','the marked animals stay together','the second sample is larger than the first'],`The method assumes the marked animals mix back in and no animals are born, die, arrive or leave in between.`),
()=>{const g=[r(50,150),r(50,150)];const n=pick([30,40]);const s0=Math.round(g[0]/sum(g)*n);return Q(`In a stratified sample of ${n} from a firm with ${g[0]} office staff and ${g[1]} factory staff, how many FACTORY staff should be chosen? (Nearest whole number; the two numbers in the sample must add to ${n}.)`,n-s0,`Round the office number, then the factory number is what is left so the total is exactly ${n}.`,`office: ${g[0]} ÷ ${sum(g)} × ${n} = ${rd(g[0]/sum(g)*n,3)} ≈ ${s0}; factory = ${n} − ${s0} = ${n-s0}`)},
()=>{const T=r(30,60),N=r(400,1200),R0=Math.round(30*T/N)||1;const M0=Math.round(N*R0/T);return Q(`A scientist estimates there are about ${N} fish in a pond. She marks ${M0} fish and releases them. In a second catch of ${T} fish, how many marked fish would she expect to find? (Nearest whole number.)`,Math.round(M0*T/N),`The proportion marked in the catch should match the proportion marked in the pond: ${M0}/${N}.`,`${M0}/${N} × ${T} = ${rd(M0*T/N,3)} ≈ ${Math.round(M0*T/N)}`)},
()=>M(`A council wants to know how residents feel about a new road. It interviews people at the train station at 8 am on a weekday. Which is the main problem? Options: the sample is likely to be biased towards commuters;  the sample is random;  the sample is too varied;  interviews take too long`,['the sample is likely to be biased towards commuters','the sample is random','the sample is too varied','interviews take too long'],`Only certain types of people will be at the station at that time, so the sample does not represent all residents.`)],
/* Very Difficult */[
()=>{const M0=r(40,80),T=r(40,80),R=r(5,15);const N=M0*T/R;const ub=M0*T/(R-1),lb=M0*T/(R+1);return Q(`${M0} newts are marked and released. Later ${T} are caught, of which ${R} are marked. One scientist thinks she may have miscounted by 1 marked newt. What is the difference between the largest and smallest population estimates if the true number of marked newts in the second catch was ${R-1}, ${R} or ${R+1}? (Nearest whole number.)`,Math.round(ub)-Math.round(lb),`Work out N = ${M0} × ${T} ÷ m for m = ${R-1} and m = ${R+1}, round each, and subtract.`,`m = ${R-1}: ${Math.round(ub)}; m = ${R+1}: ${Math.round(lb)}; difference = ${Math.round(ub)-Math.round(lb)}`)},
()=>{const g=[r(20,60),r(20,60),r(20,60)];const t=sum(g),n=pick([20,25,30]);const s=g.map(x=>x/t*n);return Q(`A gym has ${g[0]} morning, ${g[1]} afternoon and ${g[2]} evening members. A stratified sample of ${n} is taken. What is the largest number of members chosen from any one group? (Nearest whole number.)`,Math.round(Math.max(...s)),`Work out each group's share: group ÷ ${t} × ${n}.`,`${s.map(v=>rd(v,2)).join(', ')}; largest ≈ ${Math.round(Math.max(...s))}`)},
()=>M(`Two samples give different estimates of a population mean. What is the best way to get a more reliable estimate? Options: combine the samples (or take a larger sample);  use the smaller sample;  use the first sample only;  average only the highest values`,['combine the samples (or take a larger sample)','use the smaller sample','use the first sample only','average only the highest values'],`More data from properly random samples gives a more reliable estimate.`),
()=>{const p=r(1000,3000),n=pick([50,80,100]),y=r(10,n/2|0);return Q(`A random sample of ${n} people from a town of ${p} found that ${y} cycle to work. Estimate how many people in the town cycle to work, to the nearest whole number.`,Math.round(y/n*p),`Assume the sample proportion matches the town: (${y}/${n}) × ${p}.`,`${y} ÷ ${n} × ${p} = ${rd(y/n*p,2)} ≈ ${Math.round(y/n*p)}`)},
()=>{const g=r(200,500),b=r(200,500),n=pick([50,80,100]),gs=Math.round(g/(g+b)*n);return Q(`A stratified sample of ${n} is taken from ${g} girls and ${b} boys. In the sample, ${Math.round(gs*0.6)} of the girls say they walk to school. Estimate how many girls in the whole school walk to school, to the nearest whole number.`,Math.round(Math.round(gs*0.6)/gs*g),`Girls in sample = ${g} ÷ ${g+b} × ${n} ≈ ${gs}. Then scale up the proportion who walk.`,`sample girls ≈ ${gs}; proportion walking = ${Math.round(gs*0.6)}/${gs}; × ${g} = ${rd(Math.round(gs*0.6)/gs*g,2)} ≈ ${Math.round(Math.round(gs*0.6)/gs*g)}`)}]]);

/* ===== Data collection ===== */
add('Statistics','Data collection',[
/* Easy */[
()=>{const o=[['the number of pets a family has','discrete'],['the height of a plant','continuous'],['a person\'s favourite colour','qualitative (categorical)'],['shoe size','discrete']];const i=r(0,3);return M(`What type of data is "${o[i][0]}"? Options: discrete;  continuous;  qualitative (categorical);  primary`,[o[i][1],...['discrete','continuous','qualitative (categorical)','primary'].filter(x=>x!=o[i][1])],`Discrete: counted, separate values. Continuous: measured, any value in a range. Qualitative: words or categories.`)},
()=>M(`Which is primary data? Options: results from a questionnaire you wrote and handed out;  figures from a government website;  a table in a newspaper;  data from a textbook`,['results from a questionnaire you wrote and handed out','figures from a government website','a table in a newspaper','data from a textbook'],`Primary data is collected by you for your own investigation.`),
()=>{const n=r(6,19);const tally=k=>{let g='',x=6;for(let i=0;i<Math.floor(k/5);i++){for(let j=0;j<4;j++)g+=`<line x1="${x+j*7}" y1="6" x2="${x+j*7}" y2="34" stroke="currentColor" stroke-width="2"/>`;g+=`<line x1="${x-4}" y1="30" x2="${x+25}" y2="10" stroke="currentColor" stroke-width="2"/>`;x+=40}for(let j=0;j<k%5;j++)g+=`<line x1="${x+j*7}" y1="6" x2="${x+j*7}" y2="34" stroke="currentColor" stroke-width="2"/>`;return `<br><svg viewBox="0 0 ${x+40} 40" style="width:${Math.min(320,(x+40)*1.4)}px;display:block;margin:8px 0" role="img" aria-label="tally marks">${g}</svg>`};return Q(`What number is shown by these tally marks? (A group of four lines with a line across means 5.)${tally(n)}`,n,`Count the groups of 5, then add the single lines.`,`${Math.floor(n/5)} groups of 5 = ${5*Math.floor(n/5)}; plus ${n%5}; total = ${n}`)},
()=>M(`Which question is best for a survey on how much exercise people do? Options: "How many hours of exercise did you do last week? 0–2, 3–5, 6–8, more than 8";  "You exercise a lot, don't you?";  "Do you exercise?";  "How much exercise do you do?" (no options)`,['"How many hours of exercise did you do last week? 0–2, 3–5, 6–8, more than 8"','"You exercise a lot, don\'t you?"','"Do you exercise?"','"How much exercise do you do?" (no options)'],`Good questions are not leading, have a time frame, and have non-overlapping response boxes that cover every answer.`),
()=>M(`What is wrong with the response boxes 0–5, 5–10, 10–15? Options: they overlap (5 and 10 fit two boxes);  they are too wide;  they have no units;  there are too many`,['they overlap (5 and 10 fit two boxes)','they are too wide','they have no units','there are too many'],`Response boxes must not overlap and must cover every possible answer.`)],
/* Moderate */[
()=>{const a=r(5,15),b=r(5,15),c=r(5,15),d=r(5,15);const T=a+b+c+d;const miss=r(0,3);const v=[a,b,c,d];return Q(`A two-way table shows ${v[0]} boys and ${v[1]} girls who walk, and ${v[2]} boys and ${v[3]} girls who take the bus. Nobody does anything else. How many students are there altogether?`,T,`Add all four cells.`,`${v.join(' + ')} = ${T}`)},
()=>{const B=r(20,40),G=r(20,40),bw=r(5,B-5),gw=r(5,G-5);return Q(`In a class there are ${B} boys and ${G} girls. ${bw} boys and ${gw} girls walk to school. How many students do NOT walk to school?`,B+G-bw-gw,`Find how many walk, then subtract from the total.`,`total = ${B+G}; walk = ${bw+gw}; not walk = ${B+G-bw-gw}`)},
()=>M(`A survey asks "Don't you agree that school holidays are too short?" What is the problem? Options: it is a leading question;  it has too many options;  it is too personal;  it has no time frame`,['it is a leading question','it has too many options','it is too personal','it has no time frame'],`A leading question pushes people towards a particular answer.`),
()=>{const o=['the times are continuous data, so the groups should be like 0 ≤ t < 10','times cannot be grouped','the groups are too small','times are qualitative data'];return M(`Times (in minutes) are grouped as 0–10, 11–20, 21–30. What is wrong? Options: ${shuf(o.slice()).join(';  ')}`,o,`Continuous data like 10.5 minutes would not fit. Use inequalities: 0 ≤ t < 10, 10 ≤ t < 20, …`)},
()=>{const a=r(10,30),b=r(10,30),c=r(10,30);return Q(`A frequency table shows the numbers of goals in matches: 0 goals: ${a}, 1 goal: ${b}, 2 goals: ${c}. How many goals were scored in total?`,b+2*c,`Multiply each number of goals by its frequency and add.`,`0 × ${a} + 1 × ${b} + 2 × ${c} = ${b+2*c}`)}],
/* Difficult */[
()=>{const B=r(30,60),G=r(30,60),bs=r(10,B-10),gs=r(10,G-10);const tot=B+G;return P2s(`A two-way table shows ${B} boys (${bs} of them like science) and ${G} girls (${gs} of them like science). A student who likes science is chosen. What fraction are girls?`,gs,bs+gs,`Restrict to the students who like science.`,`science = ${bs+gs}; girls = ${gs}; ${frac(gs,bs+gs)}`)},
()=>M(`A pilot survey is carried out before the main survey. Why? Options: to find problems with the questions before the real survey;  to get the final results quickly;  to make the sample bigger;  to avoid using a sample`,['to find problems with the questions before the real survey','to get the final results quickly','to make the sample bigger','to avoid using a sample'],`A small trial run shows whether questions are clear and work well.`),
()=>{const ys=[r(10,30),r(10,30),r(10,30)];const tot=sum(ys)+r(10,30);return Q(`A two-way table has row totals Year 10: ${ys[0]+ys[1]}, Year 11: ${ys[2]+tot-sum(ys)} and a grand total of ${tot+ys[1]-ys[1]+0}. Year 10 has ${ys[0]} who chose art. How many in Year 10 chose a subject other than art?`,ys[1],`Year 10 total − Year 10 art.`,`${ys[0]+ys[1]} − ${ys[0]} = ${ys[1]}`)},
()=>M(`Which is the best reason for using secondary data? Options: it is quick and cheap to get;  it is always more accurate;  you know exactly how it was collected;  it is always up to date`,['it is quick and cheap to get','it is always more accurate','you know exactly how it was collected','it is always up to date'],`Secondary data saves time and money, but you may not know how reliable it is.`),
()=>{const a=r(2,9),b=r(2,9),c=r(2,9),d=r(2,9);const M2=[[a,b],[c,d]];return Q(`A two-way table: Cats — men ${a}, women ${b}; Dogs — men ${c}, women ${d}. How many more women than men are in the table?`,(b+d)-(a+c),`Total women − total men.`,`women = ${b+d}; men = ${a+c}; difference = ${(b+d)-(a+c)}`)}],
/* Very Difficult */[
()=>{const T=r(80,120),B=r(30,60),G=T-B,bl=r(10,B-10),gl=r(10,G-10);return Q(`In a survey of ${T} students, ${B} are boys. ${bl} boys and ${gl} girls are left-handed. How many girls are right-handed?`,G-gl,`Girls = ${T} − ${B}. Then subtract the left-handed girls.`,`girls = ${G}; right-handed girls = ${G} − ${gl} = ${G-gl}`)},
()=>{const t=r(60,100),w=r(20,40),c=r(10,25);const b=t-w-c;const wb=r(5,w-5);return Q(`${t} people travel to work by walking, car or bus. ${w} walk and ${c} drive. Of the walkers, ${wb} are women. ${Math.max(1,b-r(1,b-1))} bus users are men. If there are ${wb+(t-w-c-Math.max(1,b-r(1,b-1)))+r(5,c-2)} women altogether… how many people use the bus?`.replace(/ If there are .*?… how many people use the bus\?/,' How many people travel by bus?'),b,`Bus = total − walk − car.`,`${t} − ${w} − ${c} = ${b}`)},
()=>M(`Which sampling frame problem could bias a phone survey that uses only landline numbers? Options: people without landlines (often younger) are left out;  it is too random;  everyone has a landline;  phone surveys cannot be biased`,['people without landlines (often younger) are left out','it is too random','everyone has a landline','phone surveys cannot be biased'],`If some groups cannot be selected, the sample does not represent the population.`),
()=>{const f=[r(2,10),r(5,15),r(5,15),r(2,10)];const lab=['0 ≤ t < 10','10 ≤ t < 20','20 ≤ t < 30','30 ≤ t < 40'];return Q(`The table shows times in minutes.${tbl(['Time t','Frequency'],lab.map((l,i)=>[l,f[i]]))}How many people took at least 20 minutes?`,f[2]+f[3],`"At least 20" includes the groups starting at 20 and 30.`,`${f[2]} + ${f[3]} = ${f[2]+f[3]}`)},
()=>M(`An online survey about internet use is posted on a social media site. Why might the results not represent the whole population? Options: only people who use that site and the internet can respond;  the sample is too large;  online surveys are always random;  people answer too quickly`,['only people who use that site and the internet can respond','the sample is too large','online surveys are always random','people answer too quickly'],`Self-selected online samples miss people who do not use the site.`)]]);
const P2s=(q,n,d,m,w)=>QF(q,n,d,m,w);

/* ===== Tables and charts ===== */
add('Statistics','Tables and charts',[
/* Easy */[
()=>{const f=[r(2,12),r(2,12),r(2,12),r(2,12)];const l=['Mon','Tue','Wed','Thu'];const i=r(0,3);return Q(`The table shows cakes sold.${tbl(['Day',...l],[['Cakes',...f]])}How many cakes were sold on ${l[i]}?`,f[i],`Read the value from the table.`,`${f[i]}`)},
()=>{const f=[r(2,12),r(2,12),r(2,12),r(2,12)];return Q(`The table shows cakes sold.${tbl(['Day','Mon','Tue','Wed','Thu'],[['Cakes',...f]])}How many cakes were sold altogether?`,sum(f),`Add all the values.`,`${f.join(' + ')} = ${sum(f)}`)},
()=>{const f=[r(2,12),r(2,12),r(2,12),r(2,12)];return Q(`The table shows the number of goals in matches.${tbl(['Goals','0','1','2','3'],[['Frequency',...f]])}How many matches were there?`,sum(f),`The total frequency is the number of matches.`,`${sum(f)}`)},
()=>{const f=[r(2,12),r(2,12),r(2,12),r(2,12)];const mx=Math.max(...f);if(f.filter(x=>x==mx).length>1)f[0]=mx+1;return Q(`Using the table, which number of goals was most common (the mode)?${tbl(['Goals','0','1','2','3'],[['Frequency',...f]])}`,f.indexOf(Math.max(...f)),`The mode has the highest frequency.`,`highest frequency is ${Math.max(...f)}, at ${f.indexOf(Math.max(...f))} goals`)},
()=>{const t=pick([[5,'⭐'],[4,'⭐'],[10,'⭐']]);const n=r(1,5),half=pick([0,1]);return Q(`In a pictogram, one ⭐ represents ${t[0]} people. How many people does ${'⭐'.repeat(n)}${half?' and half a ⭐':''} represent?`,t[0]*n+(half?t[0]/2:0),`Multiply the number of whole symbols by ${t[0]}, then add half of ${t[0]} for a half symbol.`,`${n} × ${t[0]}${half?` + ${t[0]/2}`:''} = ${t[0]*n+(half?t[0]/2:0)}`)}],
/* Moderate */[
()=>{const a=r(5,20),b=r(5,20),c=r(5,20),d=r(5,20);return Q(`Complete the two-way table: Boys — swim ${a}, cycle ?; Girls — swim ${c}, cycle ${d}. The total number of students is ${a+b+c+d}. How many boys cycle?`,b,`Total − the three known cells.`,`${a+b+c+d} − ${a} − ${c} − ${d} = ${b}`)},
()=>{const f=[r(2,10),r(2,10),r(2,10),r(2,10),r(2,10)];return Q(`The table shows the number of pets per family.${tbl(['Pets','0','1','2','3','4'],[['Families',...f]])}How many pets are there altogether?`,f.reduce((s,x,i)=>s+x*i,0),`Multiply each number of pets by its frequency, then add.`,`${f.map((x,i)=>`${i} × ${x}`).join(' + ')} = ${f.reduce((s,x,i)=>s+x*i,0)}`)},
()=>{const f=[r(2,10),r(2,10),r(2,10),r(2,10),r(2,10)];return Q(`Using the table, how many families have at least 2 pets?${tbl(['Pets','0','1','2','3','4'],[['Families',...f]])}`,f[2]+f[3]+f[4],`"At least 2" means 2, 3 or 4.`,`${f[2]} + ${f[3]} + ${f[4]} = ${f[2]+f[3]+f[4]}`)},
()=>{const d=pick([[7,'08:15'],[8,'09:05'],[10,'10:40']]);const m=r(25,95);const st=+d[1].slice(0,2)*60+ +d[1].slice(3);const e=st+m;return Q(`A bus timetable shows a bus leaving at ${d[1]} and arriving at ${String(Math.floor(e/60)).padStart(2,'0')}:${String(e%60).padStart(2,'0')}. How many minutes does the journey take?`,m,`Count on from the start time to the end time.`,`${m} minutes`)},
()=>{const f=[r(3,12),r(3,12),r(3,12),r(3,12)];const tot=sum(f);return Q(`In a frequency table of 4 categories the frequencies are ${f.join(', ')}. What percentage of the total is the first category? Give 1 decimal place.`,rd(f[0]/tot*100,1),`Frequency ÷ total × 100.`,`${f[0]} ÷ ${tot} × 100 = ${rd(f[0]/tot*100,1)}%`)}],
/* Difficult */[
()=>{const a=r(5,20),b=r(5,20),c=r(5,20),d=r(5,20);return Q(`A two-way table has: Year 10 — French ${a}, German ?; Year 11 — French ?, German ${d}. Year 10 total = ${a+b}; French total = ${a+c}. How many Year 11 students study French?`,c,`French total − Year 10 French.`,`${a+c} − ${a} = ${c}`)},
()=>{const g=[[0,10,r(2,8)],[10,20,r(5,15)],[20,30,r(5,15)],[30,40,r(2,8)]];const tot=sum(g.map(x=>x[2]));return Q(`The grouped table shows journey times.${tbl(['Time t (min)','Frequency'],g.map(x=>[`${x[0]} ≤ t < ${x[1]}`,x[2]]))}Which class contains the median? Give the lower end of the class.`,(()=>{const k=(tot+1)/2;let c=0;for(const x of g){c+=x[2];if(c>=k)return x[0]}})(),`The median is the ${(tot+1)/2}th value. Add the frequencies until you pass it.`,`n = ${tot}; position ${(tot+1)/2}; running totals: ${g.map((x,i)=>sum(g.slice(0,i+1).map(y=>y[2]))).join(', ')}`)},
()=>{const f=[r(2,10),r(2,10),r(2,10),r(2,10),r(2,10)];const n=sum(f);let c=0,md;for(let i=0;i<5;i++){c+=f[i];if(c>=(n+1)/2){md=i;break}}if(n%2==0){let c2=0,m1,m2;for(let i=0;i<5;i++){c2+=f[i];if(m1==null&&c2>=n/2)m1=i;if(m2==null&&c2>=n/2+1)m2=i}md=(m1+m2)/2}return Q(`Using the table, find the median number of pets.${tbl(['Pets','0','1','2','3','4'],[['Families',...f]])}`,md,`There are ${n} families. The median is the ${(n+1)/2}th value. Use running totals of the frequencies.`,`n = ${n}; running totals: ${f.map((_,i)=>sum(f.slice(0,i+1))).join(', ')}; median = ${md}`)},
()=>{const a=r(5,15),b=r(5,15),c=r(5,15),d=r(5,15);return P2s(`A two-way table: Adults — tea ${a}, coffee ${b}; Children — tea ${c}, coffee ${d}. A coffee drinker is chosen at random. What is the probability they are an adult?`,b,b+d,`Restrict to coffee drinkers.`,`${b}/${b+d} = ${frac(b,b+d)}`)},
()=>{const m=r(20,40),f=r(20,40),mm=r(5,m-5),fm=r(5,f-5);return Q(`In a survey, ${m} men and ${f} women were asked if they own a bike. ${mm} men and ${fm} women said yes. What percentage of all the people surveyed own a bike? Give 1 decimal place.`,rd((mm+fm)/(m+f)*100,1),`Total yes ÷ total people × 100.`,`${mm+fm} ÷ ${m+f} × 100 = ${rd((mm+fm)/(m+f)*100,1)}%`)}],
/* Very Difficult */[
()=>{const T=r(60,100),x=r(10,20);/* algebraic two-way */const a=x,b=2*x,c=T-a-b-10;if(c<=0)return Q(`In a two-way table, the total is 80. A = 10, B = 20, C = 15. Find D.`,35,'Total − others.','80 − 45 = 35');return Q(`A two-way table has four cells. The second cell is twice the first, the fourth cell is 10, and the total is ${T}. The third cell is ${c}. Find the first cell.`,a,`Let the first cell be x: x + 2x + ${c} + 10 = ${T}.`,`3x = ${T-c-10}; x = ${a}`)},
()=>{const g=[[0,20,r(2,8)],[20,40,r(5,15)],[40,60,r(5,15)],[60,80,r(2,8)]];const est=sum(g.map(x=>x[2]*(x[0]+x[1])/2));return Q(`The grouped table shows marks.${tbl(['Mark m','Frequency'],g.map(x=>[`${x[0]} ≤ m < ${x[1]}`,x[2]]))}Use midpoints to estimate the TOTAL of all the marks.`,est,`Multiply each midpoint by its frequency, then add.`,`${g.map(x=>`${(x[0]+x[1])/2} × ${x[2]}`).join(' + ')} = ${est}`)},
()=>{const g=[[0,10,r(2,8)],[10,20,r(5,15)],[20,30,r(5,15)],[30,50,r(2,8)]];const k=r(11,19);const est=g[0][2]+g[1][2]*(k-10)/10;return Q(`The grouped table shows times.${tbl(['Time t','Frequency'],g.map(x=>[`${x[0]} ≤ t < ${x[1]}`,x[2]]))}Estimate how many times were less than ${k}, assuming values are spread evenly in each class.`,rd(est,2),`All of the first class, plus a fraction (${k-10}/10) of the second class.`,`${g[0][2]} + ${g[1][2]} × ${k-10}/10 = ${rd(est,2)}`)},
()=>{const p=r(30,60),q=r(20,p-5);return Q(`In 2024 a shop sold ${p} bikes; in 2025 it sold ${q}. By what percentage did sales fall? Give 1 decimal place.`,rd((p-q)/p*100,1),`Percentage change = change ÷ original × 100.`,`(${p} − ${q}) ÷ ${p} × 100 = ${rd((p-q)/p*100,1)}%`)},
()=>{const f=[r(2,10),r(2,10),r(2,10),r(2,10),r(2,10)];const n=sum(f);const mn0=f.reduce((s,x,i)=>s+x*i,0)/n;return Q(`Using the table, find the mean number of pets per family, to 2 decimal places.${tbl(['Pets','0','1','2','3','4'],[['Families',...f]])}`,rd(mn0,2),`Mean = (total number of pets) ÷ (number of families).`,`total pets = ${f.reduce((s,x,i)=>s+x*i,0)}; families = ${n}; mean = ${rd(mn0,2)}`)}]]);

/* ===== Bar charts and pie charts ===== */
const barSVG=(labs,vals,step)=>{const mx=Math.max(...vals);const top=Math.ceil((mx+1)/step)*step;const W0=300,H0=180,bw=W0/labs.length;let g='';for(let v=0;v<=top;v+=step){const y=H0-v/top*H0;g+=`<line x1="30" y1="${y+10}" x2="${W0+30}" y2="${y+10}" stroke="currentColor" stroke-opacity=".15"/><text x="26" y="${y+14}" font-size="10" text-anchor="end" fill="currentColor">${v}</text>`}labs.forEach((l,i)=>{const h=vals[i]/top*H0;g+=`<rect x="${30+i*bw+bw*0.2}" y="${H0-h+10}" width="${bw*0.6}" height="${h}" fill="var(--pr)" fill-opacity=".5" stroke="var(--pr)"/><text x="${30+i*bw+bw/2}" y="${H0+24}" font-size="11" text-anchor="middle" fill="currentColor">${l}</text>`});return `<br><svg viewBox="0 0 340 215" style="${W}" role="img" aria-label="bar chart">${g}<line x1="30" y1="${H0+10}" x2="${W0+30}" y2="${H0+10}" stroke="currentColor"/></svg>`};
add('Statistics','Bar charts and pie charts',[
/* Easy */[
()=>{const labs=['A','B','C','D'],vals=labs.map(()=>2*r(1,10));const i=r(0,3);return Q(`The bar chart shows votes for four options. How many votes did option ${labs[i]} get?${barSVG(labs,vals,2)}`,vals[i],`Read across from the top of the bar to the scale.`,`${vals[i]}`)},
()=>{const labs=['Mon','Tue','Wed','Thu','Fri'],vals=labs.map(()=>r(1,12));const mx=Math.max(...vals);if(vals.filter(v=>v==mx).length>1)vals[r(0,4)]=mx+1;const i=vals.indexOf(Math.max(...vals));const opts=[labs[i],...pickn(labs.filter((_,j)=>j!=i),3)];return M(`The bar chart shows rainy hours each day. On which day was it rainiest? Options: ${shuf(opts.slice()).join(';  ')}${barSVG(labs,vals,2)}`,opts,`The tallest bar shows the largest value.`)},
()=>{const t=pick([36,60,90,120,180]);const a=r(1,t/3|0);return Q(`In a pie chart of ${t} people, how many degrees represent one person?`,360/t,`The whole pie is 360°. Divide by the number of people.`,`360 ÷ ${t} = ${360/t}°`)},
()=>{const t=pick([36,60,90,120,180]),k=r(2,t/6|0);return Q(`In a pie chart showing ${t} people, ${k} people chose blue. What angle is the blue sector (°)?`,k*360/t,`Each person is ${360/t}°. Multiply by ${k}.`,`${k} × ${360/t} = ${k*360/t}°`)},
()=>{const t=pick([40,60,80,120]),ang=pick([90,180,45,60,120].filter(a=>a*t%360==0));return Q(`A pie chart shows ${t} pupils. The sector for "walk" is ${ang}°. How many pupils walk?`,ang/360*t,`Fraction of the pie = ${ang}/360. Multiply by ${t}.`,`${ang}/360 × ${t} = ${ang/360*t}`)}],
/* Moderate */[
()=>{const t=pick([30,40,60,72,90,120]);let a,b,c;do{a=r(1,t/2|0);b=r(1,t/2|0);c=t-a-b}while(c<=0);const k=pick([[a,'red'],[b,'blue'],[c,'green']]);return Q(`In a survey of ${t} people, ${a} chose red, ${b} chose blue and ${c} chose green. In a pie chart, what angle is the ${k[1]} sector (°)? Give 1 decimal place if needed.`,rd(k[0]/t*360,1),`Angle = (frequency ÷ total) × 360.`,`${k[0]} ÷ ${t} × 360 = ${rd(k[0]/t*360,1)}°`)},
()=>{const angs=[pick([60,90,120]),pick([45,60,75])];const third=360-sum(angs);const t=pick([24,48,72,120,144]);return Q(`The pie chart shows ${t} people's favourite fruit. How many chose banana?${pie([['apple',angs[0]],['orange',angs[1]],['banana',third]])}The apple sector is ${angs[0]}° and the orange sector is ${angs[1]}°.`,rd(third/360*t,2),`Find the banana angle (360° minus the others), then multiply the fraction of 360 by ${t}.`,`banana = 360 − ${angs[0]} − ${angs[1]} = ${third}°; ${third}/360 × ${t} = ${rd(third/360*t,2)}`)},
()=>{const labs=['A','B','C','D'],vals=labs.map(()=>5*r(1,8));return Q(`The bar chart shows sales. What is the total number of sales?${barSVG(labs,vals,5)}`,sum(vals),`Read every bar and add.`,`${vals.join(' + ')} = ${sum(vals)}`)},
()=>{const ang=pick([30,45,60,72,90,120]),n=r(2,20);return Q(`In a pie chart, ${n} people are shown by a sector of ${ang}°. How many people does the whole pie chart represent?`,n*360/ang,`${ang}° is ${ang}/360 of the whole. Scale up.`,`${n} × 360 ÷ ${ang} = ${n*360/ang}`)},
()=>M(`Which chart is best for showing how a whole is split into parts (like a budget)? Options: pie chart;  line graph;  scatter graph;  cumulative frequency graph`,['pie chart','line graph','scatter graph','cumulative frequency graph'],`A pie chart shows proportions of a whole.`)],
/* Difficult */[
()=>{const a=pick([60,90,120]),b=pick([60,90]);const k=2*r(1,5);return Q(`Two pie charts have the same size. Chart A shows ${36*k} people; its "yes" sector is ${a}°. Chart B shows ${18*k} people; its "yes" sector is ${b}°. How many MORE people said yes in A than in B?`,a/360*36*k-b/360*18*k,`Angles can only be compared directly if the totals are the same. Work out the actual numbers.`,`A: ${a}/360 × ${36*k} = ${a/360*36*k}; B: ${b}/360 × ${18*k} = ${b/360*18*k}; difference = ${a/360*36*k-b/360*18*k}`)},
()=>{const labs=['Y10','Y11'];let b,g;do{b=[r(2,10),r(2,10)];g=[r(2,10),r(2,10)]}while(sum(g)<=sum(b));return Q(`A dual bar chart shows boys and girls in two year groups: Year 10 boys ${b[0]}, girls ${g[0]}; Year 11 boys ${b[1]}, girls ${g[1]}. How many more girls than boys are there in total?`,sum(g)-sum(b),`Total girls − total boys.`,`${sum(g)} − ${sum(b)} = ${sum(g)-sum(b)}`)},
()=>{const t=pick([45,90,180]);const k=r(1,t/9|0);return Q(`In a pie chart of ${t} people, the sector for "car" is ${rd(k*360/t,1)}°. What percentage of people travel by car? Give 1 decimal place.`,rd(k/t*100,1),`Percentage = angle ÷ 360 × 100.`,`${rd(k*360/t,1)} ÷ 360 × 100 = ${rd(k/t*100,1)}%`)},
()=>{const v=[r(10,40),r(10,40),r(10,40)];return M(`A student draws a bar chart of shoe sales but the vertical axis starts at ${Math.min(...v)-5} instead of 0. What is the problem? Options: it makes the differences between bars look bigger than they are;  the bars are too thin;  it shows the wrong totals;  nothing is wrong`,['it makes the differences between bars look bigger than they are','the bars are too thin','it shows the wrong totals','nothing is wrong'],`A truncated axis exaggerates differences.`)},
()=>{const ang=[pick([90,120]),pick([60,90])];const t=r(2,10)*12;const rest=360-sum(ang);return Q(`A pie chart of ${t} students has sectors for walk (${ang[0]}°), bus (${ang[1]}°) and car. How many travel by car?`,rest/360*t,`Car angle = 360 − ${ang[0]} − ${ang[1]}. Then fraction × ${t}.`,`car = ${rest}°; ${rest}/360 × ${t} = ${rest/360*t}`)}],
/* Very Difficult */[
()=>{const t1=r(2,6)*60,t2=r(2,6)*60,a1=pick([90,120]),a2=pick([60,90,120]);const n1=a1/360*t1,n2=a2/360*t2;return Q(`School A (${t1} students) and school B (${t2} students) each draw a pie chart of how students travel. The "walk" sector is ${a1}° for A and ${a2}° for B. Altogether, what fraction of all the students walk? Give a fraction or decimal.`,rd((n1+n2)/(t1+t2),4),`Find the number who walk in each school, add, then divide by the total number of students.`,`A: ${n1}; B: ${n2}; total walkers = ${n1+n2}; ${n1+n2}/${t1+t2} = ${frac(n1+n2,t1+t2)}`,{d:frac(n1+n2,t1+t2)})},
()=>{const t=pick([72,90,120]);let x=r(2,8);const sect=[x,2*x,3*x];const rest=t-sum(sect);if(rest<=0)return Q(`A pie chart shows 60 people: x, 2x, 3x and 12. Find the angle for 3x.`,144,'6x + 12 = 60 → x = 8 → 3x = 24 people → 144°.','24/60 × 360 = 144');return Q(`A pie chart shows ${t} people in four groups with frequencies x, 2x, 3x and ${rest}. The sector for x is ${rd(x/t*360,4)}°. What is the angle of the 3x sector (°)?`,rd(3*x/t*360,4),`Use the x sector to find x (or use the total), then the 3x sector is 3 times as big.`,`x sector = ${rd(x/t*360,4)}°; 3x sector = 3 × ${rd(x/t*360,4)} = ${rd(3*x/t*360,4)}°`)},
()=>{const vals=[r(10,30),r(10,30),r(10,30),r(10,30)];const ang=vals.map(v=>v/sum(vals)*360);return Q(`Frequencies ${vals.join(', ')} are shown in a pie chart. What is the difference between the largest and smallest angles, to the nearest degree?`,Math.round(Math.max(...ang)-Math.min(...ang)),`Each angle = frequency ÷ ${sum(vals)} × 360.`,`angles: ${ang.map(a=>rd(a,1)).join(', ')}; difference ≈ ${Math.round(Math.max(...ang)-Math.min(...ang))}°`)},
()=>M(`Pie chart A shows 200 people and pie chart B shows 50 people. Both have a 90° sector for "yes". Which is true? Options: 4 times as many people said yes in A as in B;  the same number said yes in both;  more said yes in B;  you cannot compare pie charts at all`,['4 times as many people said yes in A as in B','the same number said yes in both','more said yes in B','you cannot compare pie charts at all'],`Same angle means same FRACTION (1/4). 1/4 of 200 = 50; 1/4 of 50 = 12.5 → 4 times as many.`),
()=>{const t=pick([36,72,120]);const p=r(10,40);const a=rd(p/100*360,1);return Q(`${p}% of people chose tea. What angle would tea have in a pie chart (°)? Give 1 decimal place if needed.`,a,`Angle = percentage of 360°.`,`${p}/100 × 360 = ${a}°`)}]]);

/* ===== Histograms ===== */
const histG=(cl)=>{const mx=Math.max(...cl.map(c=>c[2]/(c[1]-c[0])));const yl=[0.1,0.2,0.5,1,2,5,10].find(v=>mx/v<=8);const top=Math.ceil(mx*1.15/yl)*yl;const x0=cl[0][0],x1=cl[cl.length-1][1];const xl=(x1-x0)>=100?20:(x1-x0)>=50?10:5;return svgG({x0,x1,y0:0,y1:top,step:xl,lab:xl,ystep:yl,ylab:yl,bars:cl.map(c=>[c[0],c[1],c[2]/(c[1]-c[0])]),xl:'x',yl:'frequency density'})};
const HCL=()=>pick([[[0,10],[10,15],[15,20],[20,30],[30,50]],[[0,20],[20,30],[30,40],[40,60],[60,100]],[[10,20],[20,25],[25,30],[30,40]],[[0,5],[5,10],[10,20],[20,40]]]).map(([a,b])=>[a,b,(b-a)*r(1,8)]);
add('Statistics','Histograms',[
/* Easy */[
()=>{const w=pick([5,10,20]),f=r(2,20)*w/5;return Q(`A class has width ${w} and frequency ${f}. Find its frequency density.`,f/w,`Frequency density = frequency ÷ class width.`,`${f} ÷ ${w} = ${f/w}`)},
()=>{const w=pick([5,10,20]),fd=r(1,8);return Q(`A bar in a histogram has class width ${w} and frequency density ${fd}. What is the frequency?`,fd*w,`Frequency = frequency density × class width (the AREA of the bar).`,`${fd} × ${w} = ${fd*w}`)},
()=>M(`In a histogram, what does the AREA of each bar represent? Options: the frequency;  the class width;  the frequency density;  the mean`,['the frequency','the class width','the frequency density','the mean'],`Area = frequency density × width = frequency.`),
()=>{const a=pick([0,10,20]),w=pick([5,10,15,20]);return Q(`What is the class width of ${a} ≤ x < ${a+w}?`,w,`Upper bound − lower bound.`,`${a+w} − ${a} = ${w}`)},
()=>M(`Why use frequency density instead of frequency on a histogram with unequal class widths? Options: so that wide classes do not look too big;  to make the bars taller;  because frequency cannot be plotted;  to show the mean`,['so that wide classes do not look too big','to make the bars taller','because frequency cannot be plotted','to show the mean'],`With unequal widths, bar AREA must show frequency, so the height must be frequency ÷ width.`)],
/* Moderate */[
()=>{const cl=HCL();const i=r(0,cl.length-1);return Q(`The table shows grouped data.${tbl(['Class','Frequency'],cl.map(c=>[`${c[0]} ≤ x < ${c[1]}`,c[2]]))}What is the frequency density for the class ${cl[i][0]} ≤ x < ${cl[i][1]}?`,cl[i][2]/(cl[i][1]-cl[i][0]),`Frequency ÷ class width.`,`${cl[i][2]} ÷ ${cl[i][1]-cl[i][0]} = ${cl[i][2]/(cl[i][1]-cl[i][0])}`)},
()=>{const cl=HCL();const i=r(0,cl.length-1);return Q(`The histogram shows some data. Find the frequency for the class ${cl[i][0]} ≤ x < ${cl[i][1]}.${histG(cl)}`,cl[i][2],`Frequency = bar height (frequency density) × class width.`,`height = ${cl[i][2]/(cl[i][1]-cl[i][0])}; width = ${cl[i][1]-cl[i][0]}; frequency = ${cl[i][2]}`)},
()=>{const cl=HCL();return Q(`Use the histogram to find the total frequency.${histG(cl)}`,sum(cl.map(c=>c[2])),`Find the area of every bar (density × width) and add.`,`${cl.map(c=>`${c[2]/(c[1]-c[0])} × ${c[1]-c[0]}`).join(' + ')} = ${sum(cl.map(c=>c[2]))}`)},
()=>{const w1=10,w2=20,f=r(2,10)*4;return Q(`Two classes have the same frequency, ${f}. One has width ${w1}, the other width ${w2}. What is the frequency density of the WIDER class?`,f/w2,`Divide the frequency by the width.`,`${f} ÷ ${w2} = ${f/w2}`)},
()=>{const cl=HCL();const i=r(0,cl.length-1);const fd=cl[i][2]/(cl[i][1]-cl[i][0]);return Q(`In a histogram, the bar for ${cl[i][0]} ≤ x < ${cl[i][1]} has height ${fd}. How many values are in this class?`,cl[i][2],`Frequency = height × width.`,`${fd} × ${cl[i][1]-cl[i][0]} = ${cl[i][2]}`)}],
/* Difficult */[
()=>{const cl=HCL();const j=r(1,cl.length-1);const k=cl[j][0]+(cl[j][1]-cl[j][0])/2;const below=sum(cl.slice(0,j).map(c=>c[2]))+cl[j][2]/2;return Q(`Use the histogram to estimate how many values are less than ${k}.${histG(cl)}`,below,`Add the frequencies of the whole bars below ${cl[j][0]}, then the part of the next bar up to ${k} (half of it here).`,`whole bars: ${sum(cl.slice(0,j).map(c=>c[2]))}; half of ${cl[j][2]} = ${cl[j][2]/2}; total = ${below}`)},
()=>{const cl=HCL();const tot=sum(cl.map(c=>c[2]));const k=r(0,cl.length-2);const above=sum(cl.slice(k+1).map(c=>c[2]));return Q(`Use the histogram to find how many values are at least ${cl[k+1][0]}.${histG(cl)}`,above,`Add the frequencies (areas) of all the bars from ${cl[k+1][0]} upwards.`,`${cl.slice(k+1).map(c=>c[2]).join(' + ')} = ${above}`)},
()=>{const cl=HCL();const m=sum(cl.map(c=>c[2]*(c[0]+c[1])/2))/sum(cl.map(c=>c[2]));return Q(`The table shows grouped data.${tbl(['Class','Frequency'],cl.map(c=>[`${c[0]} ≤ x < ${c[1]}`,c[2]]))}Estimate the mean, to 1 decimal place.`,rd(m,1),`Use midpoints: Σ(midpoint × frequency) ÷ total frequency.`,`Σfx = ${sum(cl.map(c=>c[2]*(c[0]+c[1])/2))}; Σf = ${sum(cl.map(c=>c[2]))}; mean ≈ ${rd(m,1)}`)},
()=>{const cl=HCL();const tot=sum(cl.map(c=>c[2]));const i=r(0,cl.length-1);return Q(`Use the histogram. What percentage of the values are in the class ${cl[i][0]} ≤ x < ${cl[i][1]}? Give 1 decimal place.${histG(cl)}`,rd(cl[i][2]/tot*100,1),`Find that class's frequency and the total frequency from the bar areas.`,`class = ${cl[i][2]}; total = ${tot}; ${rd(cl[i][2]/tot*100,1)}%`)},
()=>{const fd1=r(1,5),w1=10,fd2=r(1,5),w2=pick([5,20]);return Q(`In a histogram, one bar is ${w1} wide with height ${fd1}; another is ${w2} wide with height ${fd2}. How many values are in the two classes together?`,fd1*w1+fd2*w2,`Area of each bar = frequency.`,`${fd1} × ${w1} + ${fd2} × ${w2} = ${fd1*w1+fd2*w2}`)}],
/* Very Difficult */[
()=>{const cl=HCL();const tot=sum(cl.map(c=>c[2]));const half=tot/2;let c=0,med=null;for(const x of cl){if(c+x[2]>=half){med=x[0]+(half-c)/x[2]*(x[1]-x[0]);break}c+=x[2]}return Q(`Use the histogram to estimate the median, to 1 decimal place.${histG(cl)}`,rd(med,1),`The median is the ${half}th value. Add bar areas until you reach it, then go the right fraction of the way through that bar.`,`total = ${tot}; ${half}th value; it is in the class starting at ${cl.find((x,i)=>sum(cl.slice(0,i+1).map(y=>y[2]))>=half)[0]}; median ≈ ${rd(med,1)}`)},
()=>{const k=r(2,6);const cl=[[0,10,k*10],[10,20,k*20],[20,40,k*20]];return Q(`In a histogram, the bar for 0 ≤ x < 10 has frequency ${k*10} and height ${k}. The bar for 10 ≤ x < 20 is twice as tall. The bar for 20 ≤ x < 40 has the same height as the first bar. Find the total frequency.`,k*10+k*20+k*20,`Height × width for each bar.`,`${k} × 10 + ${2*k} × 10 + ${k} × 20 = ${k*50}`)},
()=>{const cl=HCL();const tot=sum(cl.map(c=>c[2]));const j=r(0,cl.length-1);const a=cl[j][0]+(cl[j][1]-cl[j][0])/4,b=cl[j][1];const est=cl[j][2]*3/4;return Q(`Use the histogram to estimate how many values lie between ${a} and ${b}.${histG(cl)}`,est,`Assume values are spread evenly within the bar: take the fraction (${b} − ${a}) ÷ ${cl[j][1]-cl[j][0]} of its frequency.`,`fraction = ${b-a}/${cl[j][1]-cl[j][0]} = 3/4; ${cl[j][2]} × 3/4 = ${est}`)},
()=>{const f=r(5,20)*2,w=pick([5,10,20]);const sc=pick([2,4,5]);return Q(`On a histogram, a bar representing ${f} people is drawn ${w} cm wide and ${f/w*sc/sc*1} cm tall… On a histogram the scale is 1 cm² = ${sc} people. A bar 2 cm wide and 3 cm tall represents how many people?`.replace(/On a histogram, a bar .*? tall… /,''),6*sc,`Area represents frequency: find the area in cm², then use the scale.`,`area = 2 × 3 = 6 cm²; 6 × ${sc} = ${6*sc} people`)},
()=>{const cl=HCL();const est=sum(cl.map(c=>c[2]*(c[0]+c[1])/2))/sum(cl.map(c=>c[2]));return M(`Why is a mean calculated from a histogram only an estimate? Options: we use midpoints because we do not know the exact values;  the bars have different widths;  histograms are always wrong;  the total frequency is unknown`,['we use midpoints because we do not know the exact values','the bars have different widths','histograms are always wrong','the total frequency is unknown'],`Grouped data hides the actual values; using midpoints assumes values are centred in each class.`)}]]);

/* ===== Scatter graphs ===== */
const sc=(m,noise,n=12,x0=1,x1=10,c=0)=>Array.from({length:n},()=>{const x=r(x0*10,x1*10)/10;return[x,rd(m*x+c+(Math.random()*2-1)*noise,1)]});
add('Statistics','Scatter graphs',[
/* Easy */[
()=>{const t=pick(['positive','negative','none']);const pts=t=='positive'?sc(1,1.2,12,1,9,0):t=='negative'?sc(-1,1.2,12,1,9,10):Array.from({length:12},()=>[r(10,90)/10,r(10,90)/10]);return M(`What type of correlation does the scatter graph show? Options: positive;  negative;  no correlation;  perfect circle${svgG({x0:0,x1:10,y0:0,y1:10,pts,lab:2,step:1})}`,[t=='none'?'no correlation':t,...['positive','negative','no correlation','perfect circle'].filter(x=>x!=(t=='none'?'no correlation':t))],`Positive: both go up together. Negative: one goes up as the other goes down. None: no pattern.`)},
()=>{const o=[['height and shoe size','positive'],['temperature and number of coats sold','negative'],['shoe size and test score','no correlation'],['hours revised and test score','positive'],['age of a car and its value','negative']];const i=r(0,4);return M(`What correlation would you expect between ${o[i][0]}? Options: positive;  negative;  no correlation;  it is impossible to say`,[o[i][1],...['positive','negative','no correlation','it is impossible to say'].filter(x=>x!=o[i][1])],`Think about whether one tends to increase or decrease as the other increases.`)},
()=>M(`A line of best fit should… Options: follow the trend with roughly equal points on each side;  go through the first and last points;  pass through the origin;  join every point`,['follow the trend with roughly equal points on each side','go through the first and last points','pass through the origin','join every point'],`It shows the general trend and need not pass through any particular point.`),
()=>M(`What is an outlier on a scatter graph? Options: a point that does not fit the general pattern;  the highest point;  the point on the axis;  the mean point`,['a point that does not fit the general pattern','the highest point','the point on the axis','the mean point'],`Outliers lie far away from the trend of the other points.`),
()=>M(`Does strong correlation prove that one variable causes the other? Options: no, correlation does not show causation;  yes, always;  only for positive correlation;  only if there are more than 10 points`,['no, correlation does not show causation','yes, always','only for positive correlation','only if there are more than 10 points'],`Two things can be related because of a third factor (e.g. ice cream sales and sunburn both rise in summer).`)],
/* Moderate */[
()=>{const m=pick([0.5,1.5,2,3]),c=r(1,4),x=r(2,8);return Q(`A line of best fit has equation y = ${m}x + ${c}. Use it to estimate y when x = ${x}.`,m*x+c,`Substitute x into the equation of the line.`,`${m} × ${x} + ${c} = ${m*x+c}`)},
()=>{const m=pick([0.5,1,2]),c=r(0,2);const pts=sc(m,0.6,10,1,8,c);const x=r(3,7);return GR(`The scatter graph shows data with a line of best fit y = ${m==1?'':m}x + ${c}. Estimate y when x = ${x}.${svgG({x0:0,x1:10,y0:0,y1:Math.ceil(m*10+c+2),pts,fns:[t=>m*t+c],lab:2,step:1})}`,m*x+c,0.5,'',`Read up from x = ${x} to the line, then across to the y-axis.`,`y ≈ ${m} × ${x} + ${c} = ${m*x+c}`)},
()=>M(`Why is it unreliable to use a line of best fit to predict values far outside the data? Options: the trend may not continue (extrapolation);  the line is too short;  the points are too close;  the axes are wrong`,['the trend may not continue (extrapolation)','the line is too short','the points are too close','the axes are wrong'],`Predictions inside the range of the data (interpolation) are more reliable than outside it (extrapolation).`),
()=>{const t=pick(['strong positive','weak positive','strong negative','weak negative']);const m=t.includes('positive')?1:-1,nz=t.includes('strong')?0.4:2.2;const pts=sc(m,nz,14,1,9,m>0?0:10);return M(`Describe the correlation shown. Options: strong positive;  weak positive;  strong negative;  weak negative${svgG({x0:0,x1:10,y0:-2,y1:12,pts,lab:2,step:1})}`,[t,...['strong positive','weak positive','strong negative','weak negative'].filter(x=>x!=t)],`Strong: points lie close to a line. Weak: the pattern is there but spread out.`)},
()=>{const m=-pick([0.5,2,1.5]),c=r(12,16),x=r(2,6);return Q(`A line of best fit is y = ${c} − ${-m}x. Estimate y when x = ${x}.`,c+m*x,`Substitute x.`,`${c} − ${-m} × ${x} = ${c+m*x}`)}],
/* Difficult */[
()=>{const x1=r(1,3),x2=r(7,9),m=pick([1,2,0.5]),c=r(0,3);const y1=m*x1+c,y2=m*x2+c;return Q(`A line of best fit passes through (${x1}, ${y1}) and (${x2}, ${y2}). What is its gradient?`,m,`Gradient = change in y ÷ change in x.`,`(${y2} − ${y1}) ÷ (${x2} − ${x1}) = ${m}`)},
()=>{const m=pick([2,3,5]),c=r(10,30);return M(`A line of best fit for hours worked (h) against pay (£p) is p = ${m}h + ${c}. What does the gradient ${m} mean? Options: pay increases by about £${m} for each extra hour;  the starting pay is £${m};  everyone works ${m} hours;  pay is £${m} in total`,[`pay increases by about £${m} for each extra hour`,`the starting pay is £${m}`,`everyone works ${m} hours`,`pay is £${m} in total`],`The gradient is the change in p for each 1-unit change in h.`)},
()=>{const pts=sc(1,0.5,10,1,9,0);const o=[pick([1,2]),9];pts.push(o);return X(`One point does not fit the pattern of the scatter graph. Give its coordinates. (Type it like (2,9).)${svgG({x0:0,x1:10,y0:0,y1:11,pts,lab:2,step:1})}`,MH.crd(o[0],o[1]),`Look for the point far from the trend line.`,`outlier at (${o[0]}, ${o[1]})`)},
()=>{const xs=[1,2,3,4,5],ys=xs.map(x=>2*x+r(-1,1));const mx=mean(xs),my=mean(ys);return X(`Data points: ${xs.map((x,i)=>`(${x}, ${ys[i]})`).join(', ')}. A line of best fit should pass through the mean point (x̄, ȳ). Find the mean point. (Type it like (3,6.2).)`,MH.crd(rd(mx,2),rd(my,2)),`Find the mean of the x values and the mean of the y values.`,`x̄ = ${rd(mx,2)}; ȳ = ${sum(ys)} ÷ 5 = ${rd(my,2)}`)},
()=>M(`A scatter graph shows strong positive correlation between ice cream sales and drowning incidents. What is the best explanation? Options: both increase in hot weather (a third factor);  ice cream causes drowning;  drowning causes ice cream sales;  the data must be wrong`,['both increase in hot weather (a third factor)','ice cream causes drowning','drowning causes ice cream sales','the data must be wrong'],`Correlation can come from a hidden third variable.`)],
/* Very Difficult */[
()=>{const m=pick([1.5,2,2.5]),c=r(1,5);const x=r(12,20);return M(`A line of best fit y = ${m}x + ${c} was drawn using x-values from 1 to 10. Someone uses it to predict y at x = ${x}, getting ${m*x+c}. Which comment is best? Options: unreliable, because ${x} is outside the range of the data;  reliable, because the line is straight;  reliable, because the correlation is positive;  unreliable, because y is too big`,[`unreliable, because ${x} is outside the range of the data`,'reliable, because the line is straight','reliable, because the correlation is positive','unreliable, because y is too big'],`Extrapolation beyond the data assumes the trend continues, which may not be true.`)},
()=>{const x1=r(2,4),x2=r(7,9),m=pick([-1,-2,-0.5]),c=r(15,20);const y1=m*x1+c,y2=m*x2+c;return Q(`A line of best fit passes through (${x1}, ${y1}) and (${x2}, ${y2}). Find its equation y = mx + c, and give the value of c.`,c,`Gradient first: (${y2} − ${y1}) ÷ (${x2} − ${x1}). Then substitute a point to find c.`,`m = ${m}; ${y1} = ${m} × ${x1} + c; c = ${c}`)},
()=>{const xs=[2,4,6,8,10],ys=xs.map(x=>3*x+r(-2,2));const mx=mean(xs),my=mean(ys);const m=3,c=rd(my-m*mx,2);return Q(`A line of best fit with gradient 3 passes through the mean point of the data ${xs.map((x,i)=>`(${x}, ${ys[i]})`).join(', ')}. Find its y-intercept c.`,c,`Find the mean point, then c = ȳ − 3x̄.`,`mean point (${mx}, ${rd(my,2)}); c = ${rd(my,2)} − 3 × ${mx} = ${c}`)},
()=>M(`Which statement about removing an outlier from a scatter graph is best? Options: only remove it if there is a good reason it is an error;  always remove all outliers;  never draw a line of best fit with outliers;  outliers make correlation stronger`,['only remove it if there is a good reason it is an error','always remove all outliers','never draw a line of best fit with outliers','outliers make correlation stronger'],`An outlier may be a genuine value; remove it only if it is a mistake (e.g. recording error).`),
()=>{const m=pick([4,5,6]),c=r(20,40),h=r(5,12);const p=m*h+c;return Q(`For a group of workers, weekly pay (£p) and hours of overtime (h) have a line of best fit p = ${m}h + ${c} … wait: p is in tens of pounds. Estimate the pay, in pounds, for ${h} hours of overtime.`.replace(/ … wait: p is in tens of pounds\./,' (p is measured in tens of pounds).'),p*10,`Substitute h = ${h} to get p in tens of pounds, then multiply by 10.`,`p = ${m} × ${h} + ${c} = ${p}; pay = ${p} × 10 = £${p*10}`)}]]);

/* ===== Mean, median, mode and range ===== */
add('Statistics','Mean, median, mode and range',[
/* Easy */[
()=>{const a=lst(r(5,9),1,30);return Q(`Find the mean of ${a.join(', ')}. Give 2 decimal places if needed.`,rd(mean(a),2),`Mean = total ÷ how many.`,`total = ${sum(a)}; count = ${a.length}; mean = ${rd(mean(a),2)}`)},
()=>{const a=lst(2*r(2,4)+1,1,50);return Q(`Find the median of ${a.join(', ')}.`,med(a),`Put the numbers in order, then find the middle one.`,`ordered: ${srt(a).join(', ')}; median = ${med(a)}`)},
()=>{const [a,m]=mode1();return Q(`Find the mode of ${a.join(', ')}.`,m,`The mode is the most common value.`,`${m} appears most often`)},
()=>{const a=lst(r(5,9),1,60);return Q(`Find the range of ${a.join(', ')}.`,Math.max(...a)-Math.min(...a),`Range = largest − smallest.`,`${Math.max(...a)} − ${Math.min(...a)} = ${Math.max(...a)-Math.min(...a)}`)},
()=>{const a=lst(2*r(2,4),1,40);return Q(`Find the median of ${a.join(', ')}.`,med(a),`With an even number of values, the median is halfway between the two middle values.`,`ordered: ${srt(a).join(', ')}; median = ${med(a)}`)}],
/* Moderate */[
()=>{const n=r(4,8),m=r(10,30),a=lst(n-1,m-8,m+8);const last=m*n-sum(a);return Q(`The mean of ${n} numbers is ${m}. ${n-1} of them are ${a.join(', ')}. Find the missing number.`,last,`Total = mean × count. Subtract the numbers you know.`,`total = ${m} × ${n} = ${m*n}; known = ${sum(a)}; missing = ${last}`)},
()=>{const f=[r(1,8),r(1,8),r(1,8),r(1,8),r(1,8)];const n=sum(f);const tot=f.reduce((s,x,i)=>s+x*(i+1),0);return Q(`The table shows scores.${tbl(['Score','1','2','3','4','5'],[['Frequency',...f]])}Find the mean score, to 2 decimal places.`,rd(tot/n,2),`Mean = Σ(score × frequency) ÷ Σfrequency.`,`Σfx = ${tot}; Σf = ${n}; mean = ${rd(tot/n,2)}`)},
()=>{const f=[r(1,8),r(1,8),r(1,8),r(1,8),r(1,8)];const mx=Math.max(...f);if(f.filter(x=>x==mx).length>1)f[r(0,4)]=mx+1;return Q(`Using the table, what is the modal score?${tbl(['Score','1','2','3','4','5'],[['Frequency',...f]])}`,f.indexOf(Math.max(...f))+1,`The mode has the highest frequency.`,`highest frequency ${Math.max(...f)} → score ${f.indexOf(Math.max(...f))+1}`)},
()=>{const n1=r(5,15),m1=r(40,80),n2=r(5,15),m2=r(40,80);return Q(`Group A has ${n1} students with mean mark ${m1}. Group B has ${n2} students with mean mark ${m2}. Find the mean mark of all the students together, to 1 decimal place.`,rd((n1*m1+n2*m2)/(n1+n2),1),`Find each group's total, add them, then divide by the total number of students.`,`A total = ${n1*m1}; B total = ${n2*m2}; overall = ${n1*m1+n2*m2} ÷ ${n1+n2} = ${rd((n1*m1+n2*m2)/(n1+n2),1)}`)},
()=>{const a=lst(6,10,40);const k=r(2,5);return Q(`The numbers ${a.join(', ')} each have ${k} added to them. What is the new mean? Give 2 decimal places if needed.`,rd(mean(a)+k,2),`Adding the same amount to every value adds that amount to the mean.`,`old mean = ${rd(mean(a),2)}; new = ${rd(mean(a)+k,2)}`)}],
/* Difficult */[
()=>{const g=[[0,10,r(2,8)],[10,20,r(5,15)],[20,30,r(5,15)],[30,40,r(2,8)]];const m=sum(g.map(x=>x[2]*(x[0]+x[1])/2))/sum(g.map(x=>x[2]));return Q(`The table shows grouped times.${tbl(['Time t','Frequency'],g.map(x=>[`${x[0]} ≤ t < ${x[1]}`,x[2]]))}Estimate the mean, to 1 decimal place.`,rd(m,1),`Use the midpoint of each class: Σ(midpoint × f) ÷ Σf.`,`midpoints 5, 15, 25, 35; Σfx = ${sum(g.map(x=>x[2]*(x[0]+x[1])/2))}; Σf = ${sum(g.map(x=>x[2]))}; mean ≈ ${rd(m,1)}`)},
()=>{const g=[[0,10,r(2,8)],[10,20,r(5,15)],[20,30,r(5,15)],[30,40,r(2,8)]];const mi=g.reduce((b,x)=>x[2]>b[2]?x:b);if(g.filter(x=>x[2]==mi[2]).length>1)g[1][2]=mi[2]+1;const m2=g.reduce((b,x)=>x[2]>b[2]?x:b);return Q(`Using the table, what is the modal class? Give its lower bound.${tbl(['Time t','Frequency'],g.map(x=>[`${x[0]} ≤ t < ${x[1]}`,x[2]]))}`,m2[0],`The modal class has the highest frequency.`,`highest frequency ${m2[2]} → ${m2[0]} ≤ t < ${m2[1]}`)},
()=>{const n=r(5,9),m=r(10,20),x=r(25,40);const nm=(n*m+x)/(n+1);return Q(`The mean of ${n} numbers is ${m}. Another number, ${x}, is added. What is the new mean? Give 2 decimal places if needed.`,rd(nm,2),`New total ÷ new count.`,`old total = ${n*m}; new total = ${n*m+x}; ÷ ${n+1} = ${rd(nm,2)}`)},
()=>{let a;do a=lst(5,1,20);while(new Set(a).size<5);const s=srt(a);return Q(`Five different whole numbers have a median of ${s[2]}, a range of ${s[4]-s[0]} and the smallest is ${s[0]}. The other two numbers are ${s[1]} and ${s[3]}. Find the mean, to 1 decimal place.`,rd(mean(s),1),`The largest = smallest + range. Then add all five and divide by 5.`,`largest = ${s[0]} + ${s[4]-s[0]} = ${s[4]}; numbers ${s.join(', ')}; mean = ${rd(mean(s),1)}`)},
()=>{const a=lst(7,20,50);a.push(r(150,200));return M(`The data ${a.join(', ')} has one very large value. Which average best represents typical values? Options: the median, because it is not affected by the extreme value;  the mean, because it uses all the data;  the range;  the largest value`,['the median, because it is not affected by the extreme value','the mean, because it uses all the data','the range','the largest value'],`An outlier pulls the mean up, but the median stays near the middle of the data.`)}],
/* Very Difficult */[
()=>{const n=r(5,8),m=r(10,20),nm=m+r(1,4);const x=nm*(n+1)-n*m;return Q(`The mean of ${n} numbers is ${m}. When one more number is added, the mean becomes ${nm}. What number was added?`,x,`New total − old total.`,`old total = ${n*m}; new total = ${nm*(n+1)}; added = ${x}`)},
()=>{let a,c,d,e,tot;do{a=r(2,10);c=a+r(1,5);d=c+r(0,6);e=d+r(1,8);tot=2*a+c+d+e}while(tot%5);return Q(`Five whole numbers have a mode of ${a}, a median of ${c}, a range of ${e-a} and a mean of ${tot/5}. The mode is the smallest number and appears exactly twice. Find the second-largest number.`,d,`Write the numbers in order: ${a}, ${a}, ${c}, ?, largest. The largest = ${a} + ${e-a}. The total = mean × 5.`,`largest = ${e}; total = ${tot/5} × 5 = ${tot}; missing = ${tot} − ${a} − ${a} − ${c} − ${e} = ${d}`)},
()=>{const ka=r(10,20),ma=r(50,70),kb=r(10,20);const total=r(55,70);const mb=rd((total*(ka+kb)-ka*ma)/kb,2);return Q(`Class A has ${ka} students with mean ${ma}. Class B has ${kb} students. The mean of all ${ka+kb} students is ${total}. Find the mean of class B, to 2 decimal places.`,mb,`Overall total = ${total} × ${ka+kb}. Subtract class A's total, divide by ${kb}.`,`overall = ${total*(ka+kb)}; A = ${ka*ma}; B total = ${total*(ka+kb)-ka*ma}; B mean = ${mb}`)},
()=>{const g=[[0,20,r(2,8)],[20,40,r(5,15)],[40,60,r(5,15)],[60,100,r(2,8)]];const m=sum(g.map(x=>x[2]*(x[0]+x[1])/2))/sum(g.map(x=>x[2]));return Q(`The table shows grouped data with unequal classes.${tbl(['x','Frequency'],g.map(x=>[`${x[0]} ≤ x < ${x[1]}`,x[2]]))}Estimate the mean, to 1 decimal place.`,rd(m,1),`Midpoints are 10, 30, 50 and 80 (the last class is wider).`,`Σfx = ${sum(g.map(x=>x[2]*(x[0]+x[1])/2))}; Σf = ${sum(g.map(x=>x[2]))}; mean ≈ ${rd(m,1)}`)},
()=>{const x=r(2,9);const a=[x,x+3,2*x,2*x+1,3*x];return Q(`The numbers x, x + 3, 2x, 2x + 1 and 3x have a mean of ${mean(a)}. Find x.`,x,`Sum = 9x + 4, so (9x + 4) ÷ 5 = ${mean(a)}.`,`9x + 4 = ${5*mean(a)}; 9x = ${5*mean(a)-4}; x = ${x}`)}]]);

/* ===== Quartiles and interquartile range ===== */
add('Statistics','Quartiles and interquartile range',[
/* Easy */[
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`For the ordered data ${s.join(', ')}, find the lower quartile.`,q1,`With n = ${s.length} values, the lower quartile is the (n + 1) ÷ 4 = ${(s.length+1)/4}th value.`,`position ${(s.length+1)/4}; LQ = ${q1}`)},
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`For the ordered data ${s.join(', ')}, find the upper quartile.`,q3,`The upper quartile is the 3(n + 1) ÷ 4 = ${3*(s.length+1)/4}th value.`,`position ${3*(s.length+1)/4}; UQ = ${q3}`)},
()=>{const q1=r(10,30),q3=q1+r(5,30);return Q(`The lower quartile is ${q1} and the upper quartile is ${q3}. Find the interquartile range.`,q3-q1,`IQR = upper quartile − lower quartile.`,`${q3} − ${q1} = ${q3-q1}`)},
()=>M(`What does the interquartile range measure? Options: the spread of the middle 50% of the data;  the average;  the largest value;  the total`,['the spread of the middle 50% of the data','the average','the largest value','the total'],`IQR = UQ − LQ: the range of the middle half.`),
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`For the ordered data ${s.join(', ')}, find the median.`,m,`The median is the (n + 1) ÷ 2 = ${(s.length+1)/2}th value.`,`median = ${m}`)}],
/* Moderate */[
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`Find the interquartile range of ${s.join(', ')}.`,q3-q1,`Find the LQ (${(s.length+1)/4}th value) and UQ (${3*(s.length+1)/4}th value), then subtract.`,`LQ = ${q1}; UQ = ${q3}; IQR = ${q3-q1}`)},
()=>{const s=qlist();const [q1,m,q3]=quart(s);const u=shuf(s.slice());return Q(`Find the interquartile range of ${u.join(', ')}.`,q3-q1,`First put the data in order. Then find the quartiles.`,`ordered: ${s.join(', ')}; LQ = ${q1}; UQ = ${q3}; IQR = ${q3-q1}`)},
()=>M(`Why is the IQR often better than the range for measuring spread? Options: it is not affected by extreme values;  it is always bigger;  it uses every value;  it is easier to calculate`,['it is not affected by extreme values','it is always bigger','it uses every value','it is easier to calculate'],`The IQR ignores the top and bottom quarters, so outliers do not affect it.`),
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`For the data ${s.join(', ')}, how many values are above the upper quartile?`,(s.length-3)/4,`About a quarter of the values lie above the UQ.`,`n = ${s.length}; values above the ${3*(s.length+1)/4}th: ${(s.length-3)/4}`)},
()=>{const q1=r(10,30),iqr=r(5,20);return Q(`The interquartile range is ${iqr} and the upper quartile is ${q1+iqr}. Find the lower quartile.`,q1,`LQ = UQ − IQR.`,`${q1+iqr} − ${iqr} = ${q1}`)}],
/* Difficult */[
()=>{const n=pick([39,59,79,99]);return Q(`A data set has ${n} values in order. Which position is the upper quartile?`,3*(n+1)/4,`UQ position = 3(n + 1) ÷ 4.`,`3 × ${n+1} ÷ 4 = ${3*(n+1)/4}`)},
()=>{const s=qlist();const [q1,m,q3]=quart(s);const iqr=q3-q1;const ub=q3+1.5*iqr;return Q(`For the data ${s.join(', ')}, an outlier is a value more than 1.5 × IQR above the upper quartile. Above what value would a data point be an outlier?`,ub,`Find the IQR, then UQ + 1.5 × IQR.`,`LQ = ${q1}; UQ = ${q3}; IQR = ${iqr}; ${q3} + 1.5 × ${iqr} = ${ub}`)},
()=>{const a=quart(qlist()),b=quart(qlist());return M(`Group A has IQR ${a[2]-a[0]} and group B has IQR ${b[2]-b[0]}. Which statement is correct? Options: ${a[2]-a[0]<b[2]-b[0]?'A':'B'} is more consistent (less spread);  ${a[2]-a[0]<b[2]-b[0]?'B':'A'} is more consistent;  they have the same spread;  you cannot compare IQRs`,[`${a[2]-a[0]<b[2]-b[0]?'A':'B'} is more consistent (less spread)`,`${a[2]-a[0]<b[2]-b[0]?'B':'A'} is more consistent`,'they have the same spread','you cannot compare IQRs'],`A smaller IQR means the middle values are closer together: more consistent.`)},
()=>{const s=qlist();const k=r(2,5);const [q1,m,q3]=quart(s);return Q(`Every value in ${s.join(', ')} is increased by ${k}. What is the new interquartile range?`,q3-q1,`Adding the same amount to every value shifts the quartiles but does not change the spread.`,`IQR stays ${q3-q1}`)},
()=>{const s=qlist();const k=pick([2,3]);const [q1,m,q3]=quart(s);return Q(`Every value in ${s.join(', ')} is multiplied by ${k}. What is the new interquartile range?`,k*(q3-q1),`Multiplying every value multiplies the spread by the same amount.`,`old IQR = ${q3-q1}; new = ${k*(q3-q1)}`)}],
/* Very Difficult */[
()=>{const s=qlist();const [q1,m,q3]=quart(s);const iqr=q3-q1;const lb=q1-1.5*iqr,ub=q3+1.5*iqr;const test=pick([Math.round(ub+r(1,10)),Math.round(lb-r(1,10)),Math.round((q1+q3)/2)]);const out=test>ub||test<lb;return M(`For the data ${s.join(', ')}, a value of ${test} is added. Using the rule "outlier if more than 1.5 × IQR beyond a quartile" (based on the original data), is ${test} an outlier? Options: ${out?'yes':'no'};  ${out?'no':'yes'};  only if it is the largest;  you cannot tell`,[out?'yes':'no',out?'no':'yes','only if it is the largest','you cannot tell'],`LQ = ${q1}, UQ = ${q3}, IQR = ${iqr}. Limits: ${lb} and ${ub}.`)},
()=>{const k=r(1,3),n=4*k+3;const s=srt(lst(n,10,60));const [q1,m,q3]=quart(s);const s2=srt([...s.slice(0,n-1),s[n-1]+r(5,25)]);const [a,b,c]=quart(s2);return Q(`For the data ${s.join(', ')}, the largest value is changed to ${s2[n-1]}. What is the new interquartile range?`,c-a,`Changing only the largest value does not move the quartiles (they depend on positions, not the size of the extreme value).`,`new data: ${s2.join(', ')}; LQ = ${a}; UQ = ${c}; IQR = ${c-a}`)},
()=>{const q1=r(20,40),q3=q1+r(10,30),m=r(q1+1,q3-1);return M(`A box plot has LQ = ${q1}, median = ${m}, UQ = ${q3}. What fraction of the data lies between ${q1} and ${m}? Options: about 1/4;  about 1/2;  about 3/4;  all of it`,['about 1/4','about 1/2','about 3/4','all of it'],`Each section between quartiles holds about a quarter of the data.`)},
()=>{const n=pick([23,31,39]);const k=(n+1)/4;return Q(`A data set has ${n} values in order. How many values lie strictly between the lower quartile and the upper quartile?`,2*k-1,`LQ is at position ${k}, UQ at position ${3*k}. Count the values between them (not including the quartiles).`,`positions ${k+1} to ${3*k-1}: ${2*k-1} values`)},
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`For the data ${s.join(', ')}, what is (UQ − median) − (median − LQ)? (A positive answer suggests positive skew.)`,(q3-m)-(m-q1),`Compare the upper and lower halves of the box.`,`UQ − median = ${q3-m}; median − LQ = ${m-q1}; difference = ${(q3-m)-(m-q1)}`)}]]);

/* ===== Cumulative frequency ===== */
const CFD=()=>{const st=pick([[0,10],[0,20],[20,10]]);const f=[r(2,8),r(6,14),r(10,20),r(6,14),r(2,8)];const cls=f.map((v,i)=>[st[0]+i*st[1],st[0]+(i+1)*st[1],v]);return cls};
const cfPts=cl=>{let c=0;const p=[[cl[0][0],0]];cl.forEach(x=>{c+=x[2];p.push([x[1],c])});return p};
const cfRead=(cl,y)=>{const p=cfPts(cl);for(let i=1;i<p.length;i++)if(p[i][1]>=y){const [x0,y0]=p[i-1],[x1,y1]=p[i];return x0+(y-y0)/(y1-y0)*(x1-x0)}return p[p.length-1][0]};
const cfSVG=cl=>{const p=cfPts(cl),T=p[p.length-1][1];const top=Math.ceil(T/10)*10;return svgG({x0:p[0][0],x1:p[p.length-1][0],y0:0,y1:top,step:Math.max(5,(p[p.length-1][0]-p[0][0])/10),lab:(p[p.length-1][0]-p[0][0])/5,ystep:5,ylab:10,segs:p.slice(1).map((q,i)=>[p[i][0],p[i][1],q[0],q[1]]),pts:p.map(q=>[q[0],q[1]]),xl:'',yl:'cum. freq.'})};
add('Statistics','Cumulative frequency',[
/* Easy */[
()=>{const f=[r(2,10),r(2,10),r(2,10),r(2,10)];const i=r(1,3);return Q(`Frequencies of four classes are ${f.join(', ')}. What is the cumulative frequency at the end of the ${['first','second','third','fourth'][i]} class?`,sum(f.slice(0,i+1)),`Cumulative frequency is a running total.`,`${f.slice(0,i+1).join(' + ')} = ${sum(f.slice(0,i+1))}`)},
()=>M(`When plotting a cumulative frequency graph, the points are plotted at… Options: the upper end of each class;  the midpoint of each class;  the lower end of each class;  any point in the class`,['the upper end of each class','the midpoint of each class','the lower end of each class','any point in the class'],`The running total is complete only at the END of each class.`),
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));return Q(`A cumulative frequency graph ends at a height of ${T}. How many values are in the data set?`,T,`The last cumulative frequency is the total frequency.`,`${T}`)},
()=>{const cl=CFD();const p=cfPts(cl);const i=r(1,p.length-1);return Q(`Use the cumulative frequency graph: how many values are less than ${p[i][0]}?${cfSVG(cl)}`,p[i][1],`Read up from ${p[i][0]} to the curve, then across.`,`${p[i][1]}`)},
()=>{const T=pick([40,60,80,100,120]);return Q(`A cumulative frequency graph has a total of ${T}. At what cumulative frequency do you read off the median?`,T/2,`The median is at half the total.`,`${T} ÷ 2 = ${T/2}`)}],
/* Moderate */[
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const m=cfRead(cl,T/2);return GR(`Use the cumulative frequency graph to estimate the median.${cfSVG(cl)}`,rd(m,1),(cl[0][1]-cl[0][0])/5,'',`Total = ${T}. Read across from ${T/2} to the curve, then down.`,`at cumulative frequency ${T/2}: x ≈ ${rd(m,1)}`)},
()=>{const cl=CFD();const p=cfPts(cl);const i=r(1,p.length-2);const T=p[p.length-1][1];return Q(`Use the graph: how many values are AT LEAST ${p[i][0]}?${cfSVG(cl)}`,T-p[i][1],`Read the number below ${p[i][0]}, then subtract from the total.`,`below = ${p[i][1]}; total = ${T}; at least = ${T-p[i][1]}`)},
()=>{const f=[r(2,10),r(2,10),r(2,10),r(2,10),r(2,10)];return Q(`Frequencies are ${f.join(', ')}. What is the cumulative frequency for the third class?`,f[0]+f[1]+f[2],`Add the first three.`,`${f[0]} + ${f[1]} + ${f[2]} = ${f[0]+f[1]+f[2]}`)},
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const q1=cfRead(cl,T/4);return GR(`Use the cumulative frequency graph to estimate the lower quartile.${cfSVG(cl)}`,rd(q1,1),(cl[0][1]-cl[0][0])/5,'',`The lower quartile is at a quarter of the total: ${T/4}.`,`at ${T/4}: LQ ≈ ${rd(q1,1)}`)},
()=>{const cl=CFD();const p=cfPts(cl);const i=r(2,p.length-1),j=r(1,i-1);return Q(`Use the graph: how many values are between ${p[j][0]} and ${p[i][0]}?${cfSVG(cl)}`,p[i][1]-p[j][1],`Subtract the two cumulative frequencies.`,`${p[i][1]} − ${p[j][1]} = ${p[i][1]-p[j][1]}`)}],
/* Difficult */[
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const q1=cfRead(cl,T/4),q3=cfRead(cl,3*T/4);return GR(`Use the cumulative frequency graph to estimate the interquartile range.${cfSVG(cl)}`,rd(q3-q1,1),2*(cl[0][1]-cl[0][0])/5,'',`Read the LQ at ${T/4} and the UQ at ${3*T/4}, then subtract.`,`LQ ≈ ${rd(q1,1)}; UQ ≈ ${rd(q3,1)}; IQR ≈ ${rd(q3-q1,1)}`)},
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const k=cl[2][0]+cl[2][1]-cl[2][0];const x=rd((cl[1][1]+cl[2][1])/2,1);const v=cfRead(cl,0)||0;const pts=cfPts(cl);const below=pts[2][1]+(pts[3][1]-pts[2][1])/2;return GR(`Use the graph to estimate how many values are less than ${x}.${cfSVG(cl)}`,below,1,'',`${x} is halfway between ${pts[2][0]} and ${pts[3][0]}; on a straight-line section the cumulative frequency is halfway too.`,`≈ ${pts[2][1]} + (${pts[3][1]} − ${pts[2][1]}) ÷ 2 = ${below}`)},
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const k=pick([10,20,25]);const v=cfRead(cl,T*(100-k)/100);return GR(`Use the graph to estimate the value that the top ${k}% of the data are above.${cfSVG(cl)}`,rd(v,1),(cl[0][1]-cl[0][0])/5,'',`The top ${k}% starts at cumulative frequency ${100-k}% of ${T} = ${T*(100-k)/100}.`,`at ${T*(100-k)/100}: x ≈ ${rd(v,1)}`)},
()=>M(`A cumulative frequency curve is steepest in the middle. What does this tell you? Options: many values are bunched in the middle;  most values are at the ends;  the data is all the same;  the median is zero`,['many values are bunched in the middle','most values are at the ends','the data is all the same','the median is zero'],`A steep section means the running total increases quickly: lots of values there.`),
()=>{const cl=CFD();const p=cfPts(cl);const T=p[p.length-1][1];const i=r(1,p.length-2);return Q(`Use the graph: what percentage of the values are less than ${p[i][0]}? Give 1 decimal place.${cfSVG(cl)}`,rd(p[i][1]/T*100,1),`Read the cumulative frequency at ${p[i][0]} and divide by the total.`,`${p[i][1]} ÷ ${T} × 100 = ${rd(p[i][1]/T*100,1)}%`)}],
/* Very Difficult */[
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const m=cfRead(cl,T/2);const q1=cfRead(cl,T/4),q3=cfRead(cl,3*T/4);return GR(`Use the cumulative frequency graph to estimate (UQ − median) − (median − LQ), to 1 decimal place.${cfSVG(cl)}`,rd((q3-m)-(m-q1),1),3*(cl[0][1]-cl[0][0])/5,'',`Read the LQ, median and UQ at ${T/4}, ${T/2} and ${3*T/4}.`,`LQ ≈ ${rd(q1,1)}; median ≈ ${rd(m,1)}; UQ ≈ ${rd(q3,1)}; result ≈ ${rd((q3-m)-(m-q1),1)}`)},
()=>{const cl=CFD();const p=cfPts(cl);const T=p[p.length-1][1];const thr=Math.round(cfRead(cl,T*0.6));const pass=T-Math.round(T*0.6);return Q(`${T} students took a test. The pass mark is set so that 40% of students pass. About how many students pass?`,Math.round(T*0.4),`40% of ${T}.`,`0.4 × ${T} = ${rd(T*0.4,2)} ≈ ${Math.round(T*0.4)}`)},
()=>{const cl=CFD();const p=cfPts(cl);const T=p[p.length-1][1];const i=r(1,p.length-2);const f=cl.map(c=>c[2]);return Q(`The cumulative frequencies are ${p.slice(1).map(q=>q[1]).join(', ')} for classes ending at ${p.slice(1).map(q=>q[0]).join(', ')}. What is the frequency of the class ending at ${p[i+1][0]}?`,f[i],`Subtract consecutive cumulative frequencies.`,`${p[i+1][1]} − ${p[i][1]} = ${f[i]}`)},
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const q1=cfRead(cl,T/4),q3=cfRead(cl,3*T/4),m=cfRead(cl,T/2);return M(`From a cumulative frequency graph, the median is ${rd(m,1)} and the IQR is ${rd(q3-q1,1)}. A second group has median ${rd(m+5,1)} and IQR ${rd(q3-q1+6,1)}. Which comparison is correct? Options: the second group has higher values on average but they are more spread out;  the second group has lower values and is more consistent;  both groups are identical;  the first group is more spread out`,['the second group has higher values on average but they are more spread out','the second group has lower values and is more consistent','both groups are identical','the first group is more spread out'],`Compare an average (median) AND a measure of spread (IQR).`)},
()=>{const cl=CFD();const T=sum(cl.map(c=>c[2]));const k=pick([10,90]);const v=cfRead(cl,T*k/100);return GR(`Use the graph to estimate the ${k}th percentile, to 1 decimal place.${cfSVG(cl)}`,rd(v,1),(cl[0][1]-cl[0][0])/5,'',`The ${k}th percentile is at ${k}% of the total: ${T*k/100}.`,`at ${T*k/100}: ≈ ${rd(v,1)}`)}]]);

/* ===== Box plots ===== */
add('Statistics','Box plots',[
/* Easy */[
()=>{const v=five(0,40);const i=r(0,4);const n=['minimum','lower quartile','median','upper quartile','maximum'][i];return Q(`Read the ${n} from the box plot.${box([v],0,40)}`,v[i],`From left to right: minimum, LQ, median, UQ, maximum.`,`${n} = ${v[i]}`)},
()=>{const v=five(0,40);return Q(`Use the box plot to find the range.${box([v],0,40)}`,v[4]-v[0],`Range = maximum − minimum (ends of the whiskers).`,`${v[4]} − ${v[0]} = ${v[4]-v[0]}`)},
()=>{const v=five(0,40);return Q(`Use the box plot to find the interquartile range.${box([v],0,40)}`,v[3]-v[1],`IQR = UQ − LQ (the ends of the box).`,`${v[3]} − ${v[1]} = ${v[3]-v[1]}`)},
()=>M(`In a box plot, what does the line inside the box show? Options: the median;  the mean;  the mode;  the range`,['the median','the mean','the mode','the range'],`The line inside the box marks the median.`),
()=>M(`What fraction of the data lies inside the box of a box plot? Options: about half;  about a quarter;  about three quarters;  all of it`,['about half','about a quarter','about three quarters','all of it'],`The box runs from LQ to UQ: the middle 50%.`)],
/* Moderate */[
()=>{const s=qlist();const [q1,m,q3]=quart(s);return Q(`A box plot is drawn for ${s.join(', ')}. Where is the right-hand end of the box (the upper quartile)?`,q3,`UQ is the ${3*(s.length+1)/4}th value.`,`UQ = ${q3}`)},
()=>{let a,b;do{a=five(0,40);b=five(0,40)}while(a[2]==b[2]);return M(`Two box plots are shown (top: A, bottom: B). Which group has the higher median? Options: ${a[2]>b[2]?'A':b[2]>a[2]?'B':'they are equal'};  ${a[2]>b[2]?'B':'A'};  you cannot tell from box plots;  ${a[2]==b[2]?'A':'they are equal'}${box([[...a,'A'],[...b,'B']],0,40)}`,[a[2]>b[2]?'A':b[2]>a[2]?'B':'they are equal',a[2]>b[2]?'B':'A','you cannot tell from box plots',a[2]==b[2]?'A':'they are equal'],`Compare the lines inside the boxes. A: ${a[2]}, B: ${b[2]}.`)},
()=>{const v=five(0,40);return M(`From the box plot, what fraction of the values are greater than ${v[3]}? Options: about 1/4;  about 1/2;  about 3/4;  none${box([v],0,40)}`,['about 1/4','about 1/2','about 3/4','none'],`${v[3]} is the upper quartile: about a quarter of the data is above it.`)},
()=>{const v=five(0,40);const n=pick([40,60,80,100]);return Q(`A box plot represents ${n} students. About how many students scored less than the lower quartile?`,n/4,`About a quarter of the data is below the LQ.`,`${n} ÷ 4 = ${n/4}`)},
()=>{const v=five(0,40);return Q(`Use the box plot: what is the difference between the median and the lower quartile?${box([v],0,40)}`,v[2]-v[1],`Read both values and subtract.`,`${v[2]} − ${v[1]} = ${v[2]-v[1]}`)}],
/* Difficult */[
()=>{const a=five(0,40),b=five(0,40);return Q(`Two box plots are shown (A on top, B below). What is the difference between their interquartile ranges? (IQR of A − IQR of B.)${box([[...a,'A'],[...b,'B']],0,40)}`,(a[3]-a[1])-(b[3]-b[1]),`Work out each IQR (UQ − LQ), then subtract.`,`A: ${a[3]} − ${a[1]} = ${a[3]-a[1]}; B: ${b[3]} − ${b[1]} = ${b[3]-b[1]}; difference = ${(a[3]-a[1])-(b[3]-b[1])}`)},
()=>{const v=five(0,40);const iqr=v[3]-v[1];const ub=v[3]+1.5*iqr;return Q(`Use the box plot. Using "outlier if more than 1.5 × IQR above the UQ", above what value is a data point an outlier?${box([v],0,40)}`,ub,`UQ + 1.5 × IQR.`,`IQR = ${iqr}; ${v[3]} + 1.5 × ${iqr} = ${ub}`)},
()=>{const s=qlist();const [q1,m,q3]=quart(s);return X(`For the data ${s.join(', ')}, give the five values needed for a box plot, in order: minimum, LQ, median, UQ, maximum. (Type them separated by commas.)`,(()=>{const v=[s[0],q1,m,q3,s[s.length-1]].join(',');return{a:v,alt:mins([v,v.replace(/,/g,', ')]),d:v.replace(/,/g,', ')}})(),`Smallest, LQ (${(s.length+1)/4}th), median (${(s.length+1)/2}th), UQ (${3*(s.length+1)/4}th), largest.`,`${s[0]}, ${q1}, ${m}, ${q3}, ${s[s.length-1]}`)},
()=>{const v=five(0,40);const n=pick([40,80,120]);return Q(`A box plot for ${n} values is shown. About how many values lie between ${v[1]} and ${v[3]}?${box([v],0,40)}`,n/2,`The box (LQ to UQ) contains about half of the data.`,`${n} ÷ 2 = ${n/2}`)},
()=>{const v=five(0,40);return M(`The median line is much closer to the LQ than the UQ. What does that suggest? Options: the data is positively skewed;  the data is negatively skewed;  the data is symmetrical;  there are no outliers`,['the data is positively skewed','the data is negatively skewed','the data is symmetrical','there are no outliers'],`A longer upper section means the upper values are more spread out: positive skew.`)}],
/* Very Difficult */[
()=>{const a=five(10,50),b=five(10,50);const am=a[2]>b[2]?'A':'B',sp=(a[3]-a[1])<(b[3]-b[1])?'A':'B';return M(`Compare the two distributions shown (A top, B bottom). Which statement is fully correct? Options: ${am} has the higher median, and ${sp} is more consistent (smaller IQR);  ${am=='A'?'B':'A'} has the higher median, and ${sp} is more consistent;  ${am} has the higher median, and ${sp=='A'?'B':'A'} is more consistent;  they are the same${box([[...a,'A'],[...b,'B']],10,50)}`,[`${am} has the higher median, and ${sp} is more consistent (smaller IQR)`,`${am=='A'?'B':'A'} has the higher median, and ${sp} is more consistent`,`${am} has the higher median, and ${sp=='A'?'B':'A'} is more consistent`,'they are the same'],`A: median ${a[2]}, IQR ${a[3]-a[1]}. B: median ${b[2]}, IQR ${b[3]-b[1]}.`)},
()=>{const v=five(0,40);const n=pick([40,80,100]);return Q(`A box plot for ${n} values is shown. About how many values are between the median and the maximum?${box([v],0,40)}`,n/2,`From the median to the maximum is the top half of the data.`,`${n} ÷ 2 = ${n/2}`)},
()=>{const v=five(0,60,4);const n=pick([60,100,120]);const fr=pick([[1,'LQ',n/4],[3,'UQ',3*n/4]]);return Q(`A box plot for ${n} students' times is shown. About how many students took less than ${v[fr[0]]} minutes?${box([v],0,60)}`,fr[2],`${v[fr[0]]} is the ${fr[1]}.`,`${fr[1]}: ${fr[0]==1?'a quarter':'three quarters'} of ${n} = ${fr[2]}`)},
()=>{const s=qlist();const [q1,m,q3]=quart(s);const iqr=q3-q1;const lo=q1-1.5*iqr,hi=q3+1.5*iqr;const out=s.filter(x=>x<lo||x>hi).length;return Q(`For the data ${s.join(', ')}, how many values are outliers (more than 1.5 × IQR beyond a quartile)?`,out,`Find the quartiles and IQR, then the limits LQ − 1.5 × IQR and UQ + 1.5 × IQR.`,`LQ = ${q1}; UQ = ${q3}; IQR = ${iqr}; limits ${lo} and ${hi}; outliers: ${out}`)},
()=>{const v=five(0,40);const w=five(0,40);return M(`Two classes sat the same test. Class P's box plot has a larger range but a smaller IQR than class Q's. Which is the best conclusion? Options: P has more extreme values but its middle half is more consistent;  P is more consistent in every way;  Q has more extreme values;  the classes are the same`,['P has more extreme values but its middle half is more consistent','P is more consistent in every way','Q has more extreme values','the classes are the same'],`Range is affected by extremes; IQR describes the middle 50%.`)}]]);

/* ===== Comparing distributions ===== */
add('Statistics','Comparing distributions',[
/* Easy */[
()=>{const a=r(40,70),b=r(40,70);if(a==b)return M(`Group A has median 50 and group B has median 50. Which is true? Options: they have the same median;  A is higher;  B is higher;  you cannot tell`,['they have the same median','A is higher','B is higher','you cannot tell'],'Compare the medians.');return M(`Group A has a mean of ${a} and group B has a mean of ${b}. Which group did better on average? Options: ${a>b?'A':'B'};  ${a>b?'B':'A'};  they did the same;  you cannot tell`,[a>b?'A':'B',a>b?'B':'A','they did the same','you cannot tell'],`Compare the averages.`)},
()=>{const a=r(10,30),b=r(10,30);if(a==b)return M(`Both groups have range 20. Which is more consistent?`.concat(' Options: they are equally spread;  A;  B;  you cannot tell'),['they are equally spread','A','B','you cannot tell'],'Same range.');return M(`Group A has a range of ${a} and group B has a range of ${b}. Which group is more consistent? Options: ${a<b?'A':'B'};  ${a<b?'B':'A'};  they are the same;  you cannot tell`,[a<b?'A':'B',a<b?'B':'A','they are the same','you cannot tell'],`A smaller spread means more consistent.`)},
()=>M(`To compare two distributions fully, you should compare… Options: an average and a measure of spread;  only the means;  only the ranges;  the largest values`,['an average and a measure of spread','only the means','only the ranges','the largest values'],`Good comparisons mention both typical values (average) and consistency (spread).`),
()=>{const a=r(40,70),b=a+r(3,10);return Q(`Group A's median is ${a} and group B's median is ${b}. What is the difference between the medians?`,b-a,`Subtract.`,`${b} − ${a} = ${b-a}`)},
()=>M(`Which measure of spread is NOT affected by outliers? Options: interquartile range;  range;  mean;  total`,['interquartile range','range','mean','total'],`The IQR uses the middle half only.`)],
/* Moderate */[
()=>{const a=lst(7,10,40),b=lst(7,10,40);return Q(`A: ${a.join(', ')}. B: ${b.join(', ')}. What is the mean of A minus the mean of B? Give 2 decimal places.`,rd(mean(a)-mean(b),2),`Work out both means, then subtract.`,`A mean = ${rd(mean(a),2)}; B mean = ${rd(mean(b),2)}; difference = ${rd(mean(a)-mean(b),2)}`)},
()=>{const ma=r(40,60),ia=r(5,15),mb=r(40,60),ib=r(5,15);return M(`Class A: median ${ma}, IQR ${ia}. Class B: median ${mb}, IQR ${ib}. Which statement is correct? Options: ${ma>mb?'A':ma<mb?'B':'neither'} scored higher on average, and ${ia<ib?'A':ia>ib?'B':'both'} ${ia==ib?'were':'was'} more consistent;  ${ma>mb?'B':'A'} scored higher on average;  both scored the same in every way;  A's results were more spread out in every case`,[`${ma>mb?'A':ma<mb?'B':'neither'} scored higher on average, and ${ia<ib?'A':ia>ib?'B':'both'} ${ia==ib?'were':'was'} more consistent`,`${ma>mb?'B':'A'} scored higher on average`,'both scored the same in every way',"A's results were more spread out in every case"],`Compare medians for average and IQRs for spread.`)},
()=>{const a=lst(9,10,40),b=lst(9,10,40);return Q(`A: ${a.join(', ')}. B: ${b.join(', ')}. What is the range of A minus the range of B?`,(Math.max(...a)-Math.min(...a))-(Math.max(...b)-Math.min(...b)),`Find each range (largest − smallest), then subtract.`,`A range = ${Math.max(...a)-Math.min(...a)}; B range = ${Math.max(...b)-Math.min(...b)}`)},
()=>M(`A student says "Group B is better because its highest score is higher." Why is this a weak comparison? Options: one value does not represent the whole group;  the highest score is always the median;  it should compare the lowest scores;  scores cannot be compared`,['one value does not represent the whole group','the highest score is always the median','it should compare the lowest scores','scores cannot be compared'],`Compare averages and spreads, not single extreme values.`),
()=>{const a=lst(7,10,40),b=lst(7,10,40);return Q(`A: ${a.join(', ')}. B: ${b.join(', ')}. What is the median of A minus the median of B?`,med(a)-med(b),`Order each list, find each median, then subtract.`,`A median = ${med(a)}; B median = ${med(b)}; difference = ${med(a)-med(b)}`)}],
/* Difficult */[
()=>{const s1=qlist(),s2=qlist();const [a1,b1,c1]=quart(s1),[a2,b2,c2]=quart(s2);return Q(`Set P: ${s1.join(', ')}. Set Q: ${s2.join(', ')}. What is IQR(P) − IQR(Q)?`,(c1-a1)-(c2-a2),`Find each set's quartiles and IQR.`,`P: ${c1} − ${a1} = ${c1-a1}; Q: ${c2} − ${a2} = ${c2-a2}; difference = ${(c1-a1)-(c2-a2)}`)},
()=>M(`Data with one very high outlier is compared using the mean. Why might that be misleading? Options: the outlier pulls the mean up, so it may not show a typical value;  the mean ignores the outlier;  the mean is always smaller than the median;  outliers do not change the mean`,['the outlier pulls the mean up, so it may not show a typical value','the mean ignores the outlier','the mean is always smaller than the median','outliers do not change the mean'],`The median is a better average when there are extreme values.`),
()=>{const g1=[[0,10,r(2,8)],[10,20,r(5,15)],[20,30,r(2,8)]],g2=[[0,10,r(2,8)],[10,20,r(5,15)],[20,30,r(2,8)]];const m=g=>sum(g.map(x=>x[2]*(x[0]+x[1])/2))/sum(g.map(x=>x[2]));return Q(`Two grouped tables have frequencies (0–10, 10–20, 20–30): A: ${g1.map(x=>x[2]).join(', ')}; B: ${g2.map(x=>x[2]).join(', ')}. Estimate mean(A) − mean(B), to 1 decimal place.`,rd(m(g1)-m(g2),1),`Use midpoints 5, 15, 25 for both.`,`A ≈ ${rd(m(g1),2)}; B ≈ ${rd(m(g2),2)}; difference ≈ ${rd(m(g1)-m(g2),1)}`)},
()=>{const a=r(50,70),b=a-r(3,10);return M(`Boys' median time for a run is ${a} s; girls' median time is ${b} s. Which conclusion is correct? Options: on average the girls were faster;  on average the boys were faster;  the girls ran further;  you cannot compare times`,['on average the girls were faster','on average the boys were faster','the girls ran further','you cannot compare times'],`For times, a LOWER median means faster.`)},
()=>{const ma=r(40,60),mb=r(40,60),ra=r(20,40),rb=r(20,40);return M(`Which pair of statistics gives the best comparison of two distributions? Options: median and IQR for each;  only the two maxima;  only the two totals;  only the two modes`,['median and IQR for each','only the two maxima','only the two totals','only the two modes'],`An average plus a measure of spread.`)}],
/* Very Difficult */[
()=>{const a=lst(8,20,60);const b=a.map(x=>x+r(-3,3));b[7]+=r(30,50);const d=rd(mean(b)-mean(a),2),dm=med(b)-med(a);return M(`Set B is the same as set A except one value is much larger. Which statement is true? Options: B's mean is noticeably higher, but its median is about the same;  B's median is much higher but the mean is the same;  both averages are unchanged;  B's IQR must be larger`,["B's mean is noticeably higher, but its median is about the same","B's median is much higher but the mean is the same",'both averages are unchanged',"B's IQR must be larger"],`One large value raises the mean (here by ${d}) but barely moves the median (${dm}).`)},
()=>{const n1=r(10,20),m1=r(50,70),n2=r(10,20),m2=r(50,70);const all=(n1*m1+n2*m2)/(n1+n2);return Q(`Group A (${n1} people) has mean ${m1}. Group B (${n2} people) has mean ${m2}. Find the mean of everyone combined, to 2 decimal places.`,rd(all,2),`Combine totals, not means: (${n1} × ${m1} + ${n2} × ${m2}) ÷ ${n1+n2}.`,`${n1*m1} + ${n2*m2} = ${n1*m1+n2*m2}; ÷ ${n1+n2} = ${rd(all,2)}`)},
()=>{const a=five(10,50),b=five(10,50);return Q(`Two box plots (A top, B bottom). What is (median of A − median of B) + (IQR of A − IQR of B)?${box([[...a,'A'],[...b,'B']],10,50)}`,(a[2]-b[2])+((a[3]-a[1])-(b[3]-b[1])),`Read both medians and both IQRs.`,`medians ${a[2]} and ${b[2]}; IQRs ${a[3]-a[1]} and ${b[3]-b[1]}; total = ${(a[2]-b[2])+((a[3]-a[1])-(b[3]-b[1]))}`)},
()=>M(`A newspaper says "Town X is richer because its mean income is higher than Town Y's." Town X has a few billionaires. What is a better comparison? Options: compare medians, which are not distorted by a few extreme incomes;  compare the highest incomes;  compare the total incomes;  the mean is always best`,['compare medians, which are not distorted by a few extreme incomes','compare the highest incomes','compare the total incomes','the mean is always best'],`Skewed data with extreme values is better summarised by the median.`),
()=>{const s1=qlist();const [a,b,c]=quart(s1);const k=pick([2,3]);return Q(`Set A is ${s1.join(', ')}. Set B is every value of A multiplied by ${k}. What is IQR(B) − IQR(A)?`,(k-1)*(c-a),`Multiplying every value by ${k} multiplies the IQR by ${k}.`,`IQR(A) = ${c-a}; IQR(B) = ${k*(c-a)}; difference = ${(k-1)*(c-a)}`)}]]);
})();
